ALTER TABLE stories ADD COLUMN IF NOT EXISTS is_flagged TINYINT(1) DEFAULT 0;
ALTER TABLE stories ADD COLUMN IF NOT EXISTS quality_score INT DEFAULT 0;

UPDATE stories SET content_text = 'یکی بود یکی نبود. یه بزی بود به اسم بز زنگوله‌پا که سه تا بچه ناز داشت: شنگول، منگول و حبه‌ی انگور. اینا با مادرشون تو یه خونه قشنگ زندگی می‌کردن. یه روز مامان بزی فهمید یه گرگ بدجنس اومده تو محله‌شون. حسابی نگران شد و به بچه‌ها گفت: «حواستون جمع باشه! در رو رو غریبه باز نکنین. اگه من بودم در رو باز کنین، اگه گرگ بود اصلا باز نکنین.» بچه‌ها هم گفتن چشم. مامان بزی رفت صحرا. یکم بعد گرگ بدجنس اومد در زد و گفت: «منم مامانتون!» بچه‌ها گفتن: «دروغ نگو، مامان ما صداش نازکه، تو صدات کلفته.» گرگ رفت، صداشو نازک کرد و برگشت، اما بچه‌ها از زیر در دیدن دستاش سیاهه. گرگ رفت دستاشو تو آرد سفید کرد. دوباره اومد، این بار بچه‌ها دیدن پاهاش قرمز نیست. گرگ رفت به پاهاش حنا زد و وقتی برگشت، بچه‌ها گول خوردن و در رو باز کردن! گرگ یهو پرید تو خونه، شنگول و منگول رو درجا قورت داد، اما حبه‌ی انگور رفت تو سوراخ راه آب قایم شد. عصر که مامان بزی برگشت، دید در بازه و بچه‌ها نیستن. حبه‌ی انگور اومد بیرون و با گریه همه چی رو تعریف کرد. مامان بزی اول رفت سراغ شغال، اما دید کار اون نیست. بعد رفت رو پشت بوم خونه گرگ و شروع کرد به تاپ و توپ کردن. گرگ اومد بیرون و رجز خونی شروع شد! قرار شد روز جمعه با هم بجنگن. مامان بزی رفت پیش سوهان‌کار و دوتا شاخ فولادی برای خودش درست کرد. گرگ هم رفت پیش دلاک تا دندوناشو تیز کنه، اما چون پول نداشت و سر دلاک کلاه گذاشت، دلاک دندوناشو کشید و جاش پنبه گذاشت! روز جنگ رسید. گرگ قبل جنگ اونقدر آب خورد که سنگین شد. تا اومد حمله کنه، دندونای پنبه‌ایش افتاد بیرون! مامان بزی هم مهلتش نداد و با شاخ فولادی شکم گرگ رو پاره کرد. شنگول و منگول صحیح و سالم پریدن بیرون. مامان بزی بچه‌ها رو برداشت و برد خونه و بهشون گفت که دیگه هیچ‌وقت در رو روی غریبه باز نکنن.', is_flagged = 0, quality_score = 95, order_index = 1 WHERE title = 'بز زنگوله پا';
UPDATE stories SET content_text = 'وزیر بدجنسی پادشاه رو کشت و زنش رو آواره کوه و بیابون کرد. زن پادشاه قبل از کشته شدن، پسر کوچولوش رو تو دره انداخت. این بچه توسط یه شیر بزرگ شد و اسمش شد شیرزاد. سال‌ها بعد، شیرزاد که پهلوون بزرگی شده بود، عموش رو پیدا کرد و با هم تاج و تخت رو پس گرفتن. عموی شیرزاد دو تا پسر داشت اما شیرزاد رو بیشتر دوست داشت. برای اینکه دلاوری اونا رو امتحان کنه، ازشون خواست یه چیز بی‌نظیر براش بیارن. پسرا هر کدوم یه چیز قیمتی آوردن، اما شیرزاد رفت و یه چراغ جادویی پیدا کرد. تو مسیر برگشت، یه پرنده سفید مهربون مدام راهنماییش می‌کرد تا تو تله دیوها نیفته. شیرزاد با کمک این پرنده تونست هم کبوترای جادویی رو بیاره، هم انگورهای بهشتی و هم یه دختر زیبا رو از چنگ دیو سفید نجات بده. آخر سر معلوم شد اون پرنده سفید طلسم شده بوده و برای نجات شیرزاد از شر یه مار سمی، جون خودش رو فدا کرد. شیرزاد هم با اون دختر زیبا ازدواج کرد و دلاوری‌اش زبانزد همه شد.', is_flagged = 0, quality_score = 95, order_index = 2 WHERE title = 'پرنده سپید';
UPDATE stories SET content_text = 'تاجری ثروتمند می‌دید که پسرش پول‌هایش را خرج دوستان بی‌شماری می‌کند. پدر برای اینکه به پسرش درس زندگی بدهد، گوسفندی را کشت و در عبایی پیچید و گفت: «به دوستانت بگو آدم کشته‌ام و جنازه‌اش را آورده‌ام.» پسر به در خانه تمام دوستان گرمابه و گلستانش رفت، اما هیچ‌کدام او را راه ندادند. در نهایت، پدر او را به خانه یکی از دوستان قدیمی خودش برد. آن مرد بدون هیچ سؤالی جنازه خیالی را پنهان کرد و لباس‌های خونی پسر را شست. آنجا بود که پسر فهمید رفیق واقعی کیست و پدر نیز با کباب کردن همان گوسفند، این درس بزرگ را جشن گرفت.', is_flagged = 0, quality_score = 92, order_index = 3 WHERE title = 'امتحان رفقا';
UPDATE stories SET content_text = 'احمدِ کارگر پس از سال‌ها زحمت، مزدش را داد و هفت پند حکیمانه خرید! پندهایی مثل «صبور باش»، «رازت را به زنت نگو» و «چیزهای سبک را در راه بردار». او در راه بازگشت با تکیه بر همین پندها، از چاهی خطرناک جان سالم به در برد، ماری مرده برداشت که بعدها به درختی جادویی تبدیل شد و با صبوری، از کشتن اشتباهی پسر ناشناسش جلوگیری کرد! در نهایت، وقتی مردی طماع قصد داشت با فریب ثروتش را بگیرد، احمد با کمک همان پندها و هوش سرشارش، او را ناکام گذاشت و سال‌ها در کنار خانواده‌اش به خوبی و خوشی زندگی کرد.', is_flagged = 0, quality_score = 92, order_index = 4 WHERE title = 'اندرزهای حکیمانه';
UPDATE stories SET content_text = 'وزیر کینه‌توزی برای انتقام از شاهزاده‌خانمی که دست رد به سینه پسرش زده بود، پیرمرد خارکنی را متقاعد کرد تا چهل روز در غاری ادای عابدان را دربیاورد. نقشه وزیر گرفت و پادشاه که فریب ظاهر پیرمرد را خورده بود، دخترش را به عقد او درآورد. اما در شب عروسی، پیرمرد غیبش زد! وزیر او را در غار پیدا کرد و دید که واقعاً مشغول عبادت است. پیرمرد رو به وزیر کرد و گفت: «من با چهل روز عبادت قلابی داماد پادشاه شدم، حالا ببین اگر از ته دل و واقعی عبادت کنم، خدا چه مقامی به من می‌دهد!» و وزیر را با حیرت تنها گذاشت.', is_flagged = 0, quality_score = 92, order_index = 5 WHERE title = 'پیرمرد عابد';
UPDATE stories SET content_text = 'یه روز مردی تصمیم گرفت برای گذروندن زندگیش یکی از الاغ‌هاش رو بفروشه. رفت بازار، اما چهار تا لوطی حقه‌باز نقشه کشیدن که خرش رو ارزون بخرن. اولی اومد جلو و گفت: «عمو، بزت چند؟» مرد گفت: «این که خره، بز نیست!» دومی و سومی و چهارمی هم اومدن و همینو گفتن. مرد بیچاره باورش شد که اشتباهی بز آورده، پس خرش رو به قیمت یه بز بهشون فروخت! وقتی رسید خونه فهمید چه کلاهی سرش رفته. فرداش بزش رو برد بازار، اما باز همون لوطی‌ها با حقه، بز رو به قیمت یه بزغاله از چنگش درآوردن.
مرد که حسابی شاکی شده بود، تصمیم گرفت انتقام بگیره. یه سکه طلا بست به دُم خر دومش و برد بازار. لوطی‌ها اومدن و مرد گفت: «این خر جادوییه، به جای پشگل طلا میندازه!» اونا هم خر رو به یه قیمت نجومی خریدن و چند شب بیدار موندن، اما جز پشگل هیچی گیرشون نیومد! مرد زرنگ رفت کنار خونه‌اش یه قبر کند، یه منقل آتیش و چند تا سیخ برد اون تو و به زنش گفت روی قبر رو بپوشونه. لوطی‌ها که عصبانی اومده بودن، زن با گریه گفت: «شوهرم مرده، اینم قبرشه!» لوطی‌ها از حرصشون شلواراشون رو کشیدن پایین تا روی قبرش بی‌احترامی کنن! مرد هم از اون زیر با سیخ داغ محکم کوبید به پشتشون! لوطی‌ها با داد و هوار فرار کردن.
فرداش مرد با قیافه‌ی عوض‌شده رفت بازار. لوطی‌ها اومدن جنس بخرن، مرد خندید و گفت: «شما چهار نفر غلام منین! داغ من روی پشتتونه!» لوطی‌ها فهمیدن چه غلطی کردن که با این مرد درافتادن. از ترس آبروشون پول خر و بز رو کامل دادن و مرد هم با جیب پر و دل خنک برگشت خونه.', is_flagged = 0, quality_score = 92, order_index = 6 WHERE title = 'این بز است یا خر';
UPDATE stories SET content_text = 'سه تا خواهر یتیم بودن که یه روز داشتن آرزوهاشونو می‌گفتن. کوچیکه که خیلی قلب پاکی داشت گفت: «اگه زن شاه بشم، یه پسر میارم که یه ور سرش طلا باشه یه ور نقره، وقت خنده گل بریزه و وقت گریه مروارید!» شاه آرزوهاشونو می‌شنوه و با کوچیکه عروسی می‌کنه.
وقتی وقت زایمان می‌شه، خواهرهای حسود قابله رو می‌خرن و یه توله سگ رو جای بچه می‌ذارن و بچه رو می‌ندازن تو دریا! شاه هم زنشو می‌ندازه زندان. اما یه خارکن مهربون بچه رو از آب می‌گیره. پسر با خنده‌ها و گریه‌هاش خارکن رو ثروتمند می‌کنه. وقتی پسر بزرگ می‌شه، با یه نقشه‌ی حساب‌شده و یه جوجه‌ی چوبی سر سفره‌ی شاه، راز توله سگ رو برملا می‌کنه. شاه با دیدن سر طلایی پسرش همه‌چیز رو می‌فهمه، زن بی‌گناهش رو از زندان درمیاره و خواهرای بدجنس رو به سزای عملشون می‌رسونه.', is_flagged = 0, quality_score = 92, order_index = 7 WHERE title = 'پادشاه و سه دخترش (1)';
UPDATE stories SET content_text = 'پسر جوونی رفت تو یه شهر دیگه و از قضا شاهین بخت روی شونه‌اش نشست و شد داماد پادشاه. اما وزیر بدجنس که بهش حسودی می‌کرد، مدام اونو به ماموریت‌های خطرناک می‌فرستاد. اول فرستادش دنبال اسب پری‌زاد. پسر تو این مسیر یه دختر پری‌زاد رو از چنگ یه دیو نجات داد و شیشه عمر دیو رو شکوند. وزیر ول‌کن نبود و فرستادش خونه جادو. پسر با راهنمایی‌های دختر پری‌زاد، از پس چهل تا دختر جادوگر برومد و کفش طلایی رو برای پادشاه آورد. آخر سر وزیر به پادشاه گفت که پسر رو بفرستن دنیای مرده‌ها تا از اجدادشون خبر بیاره! اما دختر پری‌زاد که خیلی باهوش بود، یه آدمک ساخت و انداخت تو آتیش و نامه‌ای از زیر خاکستر درآورد که توش نوشته بود اجداد وزیر دلشون براش تنگ شده! وزیر طمع‌کار هم به هوای دیدن اجدادش پرید تو آتیش و سوخت و پسر جوون و پری‌زاد با آرامش به زندگیشون ادامه دادن.', is_flagged = 0, quality_score = 92, order_index = 8 WHERE title = 'پری زاد';
UPDATE stories SET content_text = 'شاهزاده‌ای تو یه خیار جادویی یه دختر زیبا پیدا کرد که مثل ماه شب چهارده می‌درخشید. شاهزاده دختر رو گذاشت رو درخت و رفت براش لباس بیاره. همون موقع یه کنیز حسود اومد و با دیدن زیبایی دختر، اونو هل داد پایین. دختر تبدیل به یه کبوتر شد و فرار کرد! کنیز خودش رو جای دختر جا زد و با شاهزاده عروسی کرد. وقتی کبوتر می‌اومد رو بوم قصر، کنیز بهونه گرفت و گفت کبوتر رو بکشید. از خون کبوتر یه درخت سبز شد. باز کنیز دستور داد درخت رو ببرن! یه پیرزن مهربون تیکه‌ای از چوب درخت رو برد خونه‌اش و از اون چوب همون دختر زیبا بیرون اومد. آخر سر تو یه مهمونی، دختر با آواز خوندن داستانش رو برای شاهزاده تعریف کرد و انگشتری که شاهزاده بهش داده بود رو نشون داد. شاهزاده هم که فهمید گول خورده، کنیز بدجنس رو مجازات کرد و با عشق واقعی‌اش عروسی کرد.', is_flagged = 1, quality_score = 92, order_index = 9 WHERE title = 'پسر پادشاه و کنیز';
UPDATE stories SET content_text = 'مردی تو راه سفر گرفتار طوفان و دریا شد. دست و پا زد تا یه موجود مرموز نجاتش داد، به شرطی که یه سال بعد یکی از دختراش رو بده بهش. مرد قبول کرد و یه گردنبند مروارید هم برا دختر کوچیکش سوغات آورد. سال بعد غلامی اومد و دختر رو با خودش برد به یه کاخ خیلی قشنگ. دختر اونجا با یه شاهزاده‌ی طلسم‌شده ازدواج کرد. مادر دختر وقتی به دیدنش اومد، یادش داد که چطوری بیدار بمونه و راز شوهرش رو بفهمه. اما شاهزاده بیدار شد و طلسم شکست و غیبش زد! دختر که حالا باردار هم بود، کلی آواره‌ی کوه و بیابون شد تا دوای شکست‌وبست رو برای شوهرش پیدا کنه. بالاخره با کمک یه غلام باوفا و کلی ماجراجویی سخت، دوا رو از قصر دیوها و پادشاهای ظالم پیدا کرد و به سرزمین پریان برگشت. شوهرش رو نجات داد و با هم در آرامش زندگی کردن.', is_flagged = 0, quality_score = 92, order_index = 10 WHERE title = 'پسر شاه پریان';
UPDATE stories SET content_text = 'یکی بود یکی نبود. پادشاهی بود که بچه‌دار نمی‌شد، تا اینکه با دختری ازدواج کرد و صاحب یه دختر قشنگ شد. هووها از حسادت یه توله‌سگ جای نوزاد گذاشتن و بچه رو دادن به یه پیرزن تا سر به نیستش کنه. پادشاه هم از عصبانیت زنشو انداخت زندان تا اینکه مرد. پیرزن دلش نیومد بچه رو بکشه و اونو مثل دسته گل بزرگ کرد. دختر انقدر زیبا و هنرمند شد که لنگه نداشت. یه روز پادشاه از پنجره دختر رو دید و عاشقش شد و رفت خواستگاری! دختر که فهمیده بود پادشاه در واقع پدرشه، برای فرار نقشه کشید. از پیرزن خواست یه تونل زیرزمینی بکنه و یه لباس از پوست حیوانات براش بدوزه. شب عروسی، دختر لباس پوستین رو پوشید، از تونل فرار کرد و شد مثل یه حیوون پشمالو. تو یه کشور دیگه، برادرزاده‌ی ملکه پیداش کرد و بردش قصر. ملکه که پسرش گم شده بود، از پشمالو خوشش اومد. یه شب پشمالو دید آشپز بدجنس قصر میره سر یه چاه و به یه پسر لاغر و مریض که همون پسر گم‌شده‌ی ملکه بود، غذای مونده میده و کتکش می‌زنه. پشمالو پسر رو نجات داد و برد پیش مادرش. همه از خوشحالی بال درآوردن. یه روز که قصر خلوت بود، پشمالو لباس پوستینش رو درآورد تا حمام کنه. پسر پادشاه که حالش خوب شده بود، اونو دید و فهمید پشمالو چه دختر زیباییه! شب به زور ازش خواست لباسش رو دربیاره و ملکه هم کلی ذوق کرد. پدرِ دختر هم که فهمید چه اشتباهی کرده، آدمای بدجنس رو مجازات کرد و تاج و تختش رو داد به دخترش. دختر با پسر پادشاه همسایه عروسی کرد و هفت شبانه‌روز جشن گرفتن.', is_flagged = 0, quality_score = 92, order_index = 11 WHERE title = 'پشمالو';
UPDATE stories SET content_text = 'پسر جوانی به نام قباد که از سادگی بیش از حد خانواده‌اش خسته شده بود، راهی سفر شد تا مردمی عاقل‌تر پیدا کند. اما در هر شهری که قدم گذاشت، با آدم‌هایی عجیب‌تر روبرو شد! در یک جا مردم برای تمیز کردن کاسه پول می‌دادند، در جای دیگر می‌خواستند پای عروس قدبلند را ببرند تا از در رد شود، و در شهری دیگر نزدیک بود دست دختری را ببرند چون نمی‌دانست پنیر را رها کند تا دستش از کوزه بیرون بیاید! قباد با کمی هوش مشکلات همه را حل کرد و در نهایت به این نتیجه رسید که خانواده ساده‌دل خودش از همه این مردم باهوش‌ترند، پس با کمال میل به خانه برگشت!', is_flagged = 0, quality_score = 90, order_index = 12 WHERE title = 'افراد ساده لوح';
UPDATE stories SET content_text = 'در روزگاران قدیم، دختری زیبا به نام شهربانو زندگی می‌کرد که مادرش را از دست داده بود. پدرش با لجبازی می‌خواست طبق وصیت عجیب همسرش، با دختری که کفش مادر به پایش بخورد ازدواج کند و از قضا آن کفش اندازه پای شهربانو بود! شهربانو که چاره‌ای نداشت، به مزار مادر پناه برد و در خواب راه چاره را یافت. او در یک کوزه طلایی (پیرسوک) پنهان شد. پدر از غصه دیوانه شد و پیرسوک را در بازار فروخت. کوزه به دست پسر پادشاه افتاد و او عاشق دختری شد که پنهانی از کوزه بیرون می‌آمد. با وجود حسادت‌ها و نقشه‌های شوم دخترعموی شاهزاده، عشق پیروز شد و شهربانو و شاهزاده به وصال هم رسیدند.', is_flagged = 0, quality_score = 90, order_index = 13 WHERE title = 'پیر سوک طلا';
UPDATE stories SET content_text = 'روزی حضرت عزرائیل برای قبض روح پیرمردی آمد، اما پیرمرد با التماس از او خواست جانش را نگیرد. عزرائیل دلش سوخت و مهلت داد. فصل بهار شد، پیرمرد گفت: «بهاره، وقت کاره، من نمی‌رم!» تابستان گفت: «وقت درو و خرمنه، من نمی‌رم!» پاییز و زمستان هم بهانه‌هایی مثل سرما و یخبندان آورد. سال‌های طولانی گذشت و پیرمرد آن‌قدر عمر کرد که هفت نسل بعد از خودش را دید. اما دیگر کاملاً از کار افتاده بود و کسی به او اعتنایی نمی‌کرد. بالاخره از زندگی خسته شد و رو به آسمان گفت: «خدایا، اگر مرگ نبود، زندگی ارزش نداشت. عزرائیل را بفرست!» عزرائیل هم آمد و او را راحت کرد.', is_flagged = 0, quality_score = 90, order_index = 14 WHERE title = 'پیرمرد و عزرائیل';
UPDATE stories SET content_text = 'دو تا جوون به اسم ابوالشر و ابوالخیر با هم راهی سفر شدن. ابوالشر که بدجنس بود، نونِ ابوالخیر رو خورد ولی از نون خودش به اون نداد و تو بیابون ولش کرد. ابوالخیرِ گرسنه رفت زیر یه درخت استراحت کنه که حرف‌های سه تا کبوتر رو شنید. اونا از راز گنجِ یه کفاش، چشمه‌ی آب پنهان شهر و درمانِ مریضیِ دختر پادشاه می‌گفتن. ابوالخیر با خوش‌قلبی رفت گنج رو به کفاش نشون داد، برای مردم شهر آب درآورد و جون دختر پادشاه رو نجات داد. شاه هم دخترش رو به عقد اون درآورد و به خواست ابوالخیر یه نونوایی ساختن که به همه مردم نون مجانی می‌داد. یه روز ابوالشرِ گرسنه و دربه‌در رسید به همون نونوایی و رفیقش رو دید که به چه ثروت و مقامی رسیده. با حسادت راز موفقیتش رو پرسید. ابوالخیر اون رو برد همون‌جا زیر درخت انجیر. ابوالشر منتظر نشست تا رازها رو بشنوه، اما دیوها فهمیدن که یکی داره حرفاشون رو گوش می‌ده. اونو گرفتن و به سزای بدذاتیش تیکه‌تیکه‌ش کردن.', is_flagged = 0, quality_score = 90, order_index = 15 WHERE title = 'تبهکار و نیکوکار';
UPDATE stories SET content_text = 'هفت تا دختر شاد و زیبا بودن که یه روز تو جنگل سرگرم رقص و آواز شدن و شب شد. بزرگترین و عاقل‌ترینشون اسمش «تمتی» بود. از شانس بد، گیر یه گله «الازنگی» (دیوهای وحشتناک) افتادن. دیوها نقشه کشیدن تا دخترا رو بخورن. یه دیو پیر به اسم تاته الازنگی اومد و با چرب‌زبونی و دروغ دخترا رو گول زد و باهاشون طرح دوستی ریخت. اما تمتی باهوش بود و فهمید چه خبره. دخترا فرار کردن و تو یه درخت جادویی پنهان شدن. الازنگی‌ها فقط تونستن انگشت تمتی رو که بیرون مونده بود گاز بگیرن، اما انگشت دوباره سبز می‌شد! بعد از رفتن دیوها، دخترا آواره شدن و تو یه قلعه‌ی بزرگ پناه گرفتن. اما از بخت بد، این قلعه هم مال یه الازنگی دیگه بود! تمتی با زیرکی و سیاست، خودش رو تو دل این دیو هم جا کرد و وقتی اعتمادش رو جلب کرد، ازش شمشیر، اسب تندرو و لباس مردونه خواست. دخترا فرار کردن و تو راه کلی تله واسه الازنگی گذاشتن. دیو احمق دنبالشون کرد و تمتی با گول زدنش باعث شد تو رودخونه غرق بشه. دخترا بعد از کلی ماجرا و امتحان شدن توسط مردم روستاهای مختلف، بالاخره صحیح و سالم به خونه برگشتن. تمتی که از دست نامادریش به خاطر یه ماجرای قدیمی حسابی دلخور بود، باعث شد نامادریش به سزای اعمالش برسه و خودشون با آرامش زندگی کنن.', is_flagged = 0, quality_score = 90, order_index = 16 WHERE title = 'تمتی';
UPDATE stories SET content_text = 'می‌گن تو زمانای خیلی قدیم، یه روستای باصفا بود که مردمش با هم کار می‌کردن و مهربون بودن. تا اینکه یه دیو سیاه، چشمه پری و تمام روستایی‌ها رو طلسم کرد و همه چی به سنگ تبدیل شد. هزار سال گذشت تا یه روز نیمه‌ظهر، یه جوون شجاع به اسم مراد از خواب بیدار شد. دور و برش رو نگاه کرد و دید همه چی مثل مجسمه خشک شده. مراد سوار اسبش شد و رفت سمت کوه تا رسید به یه درخت عجیب که زنده بود! اونجا صدای دو تا پرنده رو شنید که می‌گفتن طلسم فقط با بیدار شدن پری چشمه می‌شکنه. مراد با شجاعت تمام رفت سراغ دیو سنگی، اونو نابود کرد و بعد تن پری رو با عصاره اون درخت جادویی شست. پری که چشماش رو باز کرد، یهو زندگی به روستا برگشت! آب چشمه دوباره جوشید، پرنده‌ها پرواز کردن و مردم از خواب هزارساله بیدار شدن. از اون روز به بعد، مردم همیشه مراقب چشمه بودن، ولی می‌گن بعد از اون طلسم، کم‌کم حرص و طمع اومد تو دل آدما و دیگه اون یک‌رنگی قدیمیا از بین رفت.', is_flagged = 0, quality_score = 90, order_index = 17 WHERE title = 'چشمه پری';
UPDATE stories SET content_text = 'روزی روزگاری شاه عباس پارچه‌ی کلفتی رو به یه خیاط داد تا براش لباس بدوزه. خیاط یک ماه وقت گرفت و با شاگردش، اوستا ابراهیم، مشغول کار شد. روز بیستم، شاه با لباس مبدل رفت دکان خیاطی تا سر و گوشی آب بده. همون موقع خیاط به ابراهیم که داشت چرت می‌زد گفت: «پاشو گل‌های لباس شاه عباسی رو بدوز، وقت زیادی نداریم!» ابراهیم خواب‌آلود جواب داد: «اِ... داشتم خواب آفتاب و ماه و ستاره رو می‌دیدم، نذاشتی!» شاه که این حرف رو شنید، رفت بارگاه و ابراهیم رو احضار کرد تا خوابش رو تعریف کنه. اما ابراهیم ترسید و زد زیرش. شاه هم عصبانی شد و انداختش زندان! مدتی گذشت تا اینکه پادشاه یه کشور دیگه، نامه‌ای فرستاد و سه تا معمای سخت پرسید و تهدید کرد اگه حل نشن، جنگ راه می‌ندازه. معمای اول این بود که باید سر و ته یه خنجر رو توی غلافش تشخیص می‌دادن. هیچ‌کدوم از دانشمندای شاه نتونستن کاری کنن. دختر شاه که یه بار ابراهیم رو تو زندان دیده و دلباخته‌اش شده بود، رفت پیشش. ابراهیم گفت: «به پدرت بگو به شرطی که دخترش رو به عقدم دربیاره حلش می‌کنم. راهش اینه که غلاف رو سه بار بندازی هوا، سمتی که زودتر بیاد پایین، سنگین‌تره و دسته خنجره!» معما حل شد و شاه برای پادشاه همسایه نوشت: «این که چیزی نبود، یه جوون شونزده ساله حلش کرد!»
معمای دوم تشخیص دو تا جوون شبیه هم بود که کدوم دختره و کدوم پسر. باز هم دختر شاه جواب رو از ابراهیم گرفت. ابراهیم یه دست‌بند طلا و یه کمربند طلا گذاشت جلوشون. اونی که دست‌بند رو برداشت دختر بود و اون یکی پسر. معمای سوم هم تشخیص مادر و کره‌ی دو تا اسب شبیه هم بود. ابراهیم دو تا توبره جو خواست که یکیش سمی بود. اسب مادر رفت سمت توبره سمی تا بچه‌اش اون رو نخوره! شاه عباس که حسابی کیف کرده بود، دخترش رو به عقد ابراهیم درآورد.
پادشاه همسایه که خیلی لجمش گرفته بود، گفت باید این جوون رو بفرستید پیش من وگرنه جنگ می‌شه. ابراهیم با یه توپ جادویی رفت اونجا و با کمک دختر پادشاه همسایه، سخت‌ترین معمای اون شاه رو هم حل کرد و شرط کرد که با اون دختر هم ازدواج کنه! سال‌ها بعد، یه روز شاه عباس رفت به قصر ابراهیم. دید ابراهیم نشسته، دختر شاه عباس دست راستش، دختر پادشاه همسایه دست چپش، و پسر کوچولوش هم روی زانوش نشسته. ابراهیم خندید و گفت: «قبله‌ی عالم! اون روز خواب دیدم آفتاب دست راستم، ماه دست چپم و ستاره روی زانوم نشسته. آفتاب دختر شماست، ماه دختر اون پادشاهه، و ستاره هم پسرمه!» شاه عباس با لبخند گفت: «عجب خوابی دیدی و چه قشنگ هم تعبیر شد!»', is_flagged = 0, quality_score = 90, order_index = 18 WHERE title = 'اوستا ابراهیم';
UPDATE stories SET content_text = 'یکی بود یکی نبود. تو شهر زیبای بلخ، یه باغبان پیر و ثروتمند باغ خیلی قشنگی داشت. یه روز یه پرنده‌ی کوچولو اومد تو باغ و شروع کرد به چیدن و انداختن میوه‌های کال و رسیده رو زمین! باغبان حسابی شاکی شد و تله گذاشت و پرنده‌ی شیطون رو گرفت. وقتی خواست بکشتش، پرنده به زبون اومد و گفت: «منو نکش! من داشتم کمکت می‌کردم. این میوه‌ها مسموم بودن و من ریختمشون دور تا کسی نمیره! اگه ولم کنی، سه تا پند طلایی بهت می‌دم.» باغبان که دلش نرم شده بود، قبول کرد.
پرنده گفت: «پند اول: هرگز به کسی که نمی‌شناسی اعتماد نکن. پند دوم: چیزای غیرممکن رو باور نکن. پند سوم: برای چیزی که از دستت رفته، غصه نخور.» باغبان پرنده رو آزاد کرد. پرنده پرید رو یه شاخه نشست و خندید و گفت: «ای مرد ساده! تو شکم من یه مروارید به بزرگی یه تخم‌مرغ بود، از دستت پرید!» باغبانِ طمع‌کار از غصه زد تو سر خودش و لباساشو پاره کرد. پرنده خندید و گفت: «دیدی پندام به دردت نخورد؟ اولاً چرا به حرف یه پرنده‌ی ناشناس اعتماد کردی؟ دوماً شکم منِ فسقلی چطور یه مروارید قد تخم‌مرغ جا می‌گیره؟ سوماً مگه نگفتم برای چیزی که از دست رفته غصه نخور؟» پرنده اینو گفت و پر کشید و رفت، و باغبان موند و یه دنیا پشیمونی.', is_flagged = 0, quality_score = 90, order_index = 19 WHERE title = 'باغبان و پرنده کوچک';
UPDATE stories SET content_text = 'یه بازرگانی قبل از سفر به زنش که باردار بود گفت: «اگه پسر آوردی که هیچی، ولی اگه دختر بود، بکشش!» بازرگان هفت تا پسر داشت و اتفاقا هشتمی دختر شد. پسرا نذاشتن مادرشون خواهر کوچولوشون رو بکشه و اونو سپردن به یه پیرزن همسایه. بازرگان برگشت و بهش گفتن دختر مرد. اما بعدا از همسایه‌ها شنید که دختر زنده است! با عصبانیت راه افتاد که دختر رو بکشه. هفت تا برادر سریع رفتن، خواهرشون رو برداشتن و فرار کردن. شب تو سرمای بیابون، برادرا دور خواهر حلقه زدن تا گرمش کنن. همونجا یه معجزه شد؛ خواهر تبدیل شد به یه بوته گل محمدی و برادرا شدن هفت تا سرو سبز بلند! مدتی بعد، بازرگان از همون‌جا رد می‌شد. خواست گلی بچینه که بوته خودش رو کشید کنار و خوند: «برادرا، بابا اومده گل بچینه، بدم یا نه؟» درختا گفتن: «نه!» بازرگان جا خورد و رفت خونه به زنش گفت چه اتفاقی افتاده. زن رفت همونجا و خواست گل بچینه، بوته باز خوند و این بار برادرا گفتن: «ننه زحمت کشیده، گل بهش بده.» مادر گل رو برد خونه. بازرگان وقتی گل رو دید، از کارش حسابی پشیمون شد و گریه کرد. زنش گفت: «باید تا می‌تونی به فقیرها کمک کنی تا خدا ببخشدت.» بازرگان تموم ثروتش رو بخشید. همون موقع گل محمدی و سروها دوباره تبدیل به بچه‌ها شدن و برگشتن خونه. بازرگان با دیدن بچه‌هاش از خوشحالی پر درآورد و هفت شبانه‌روز جشن گرفت.', is_flagged = 0, quality_score = 90, order_index = 20 WHERE title = 'بوته گل محمدی و هفت سرو';
UPDATE stories SET content_text = 'یه پادشاه ستمگری بود که مردم از دست مالیات‌ها و ظلمش به ستوه اومده بودن. وزیرا و وکلای دربار که دیدن دیگه کارد به استخون رسیده، با یکی از زن‌های شاه همدست شدن. شبونه شاه رو دزدیدن و بردن تو یه سرداب تاریک! مردم دورش جمع شدن و گفتن: «یک سال باس بشینی اینجا تا وزیر به جات حکومت کنه و بفهمی شاهی یعنی چی! اگه قبول نکنی خونت پای خودته.» شاه از ترس قبول کرد و وزیر تو این یک سال با مردم مهربونی کرد و مالیات‌ها رو کم کرد.
بعد از یک سال، شاه دوباره برگشت رو تخت. اولش قول داد خوب باشه ولی چند روز نگذشت که دوباره همون شاه ظالم قبلی شد. این بار مردم و وزرا تصمیم گرفتن تو شکارگاه کمین کنن و کلکش رو بکنن. وقتی پسر شاه خواست انتقام بگیره، اون دستخطی که شاه تو سرداب نوشته بود رو نشونش دادن و گفتن: «ما پادشاه عادل می‌خوایم، نه یه ظالم.»', is_flagged = 0, quality_score = 90, order_index = 21 WHERE title = 'پادشاه ظالم که رعیت او را از سلطنت برکنار کرد';
UPDATE stories SET content_text = 'دختر پادشاه یه روز به باباش گفت: «من تو دامن تو نشستم ولی در اصل رو بخت و اقبال خودم نشستم!» شاه عصبانی شد و گفت باید با یه پسر کچل و تنبل به اسم «لنتی» عروسی کنی و از قصر بیرونش کرد. دختر باهوش، با فروش جواهراتش تجارت راه انداخت و لنتی رو فرستاد پیش تاجرها تا کار یاد بگیره.
لنتی تو سفرش رفت ته یه چاه و با یه دیو رفیق شد! دیو کچلی اونو خوب کرد و حسابی زرنگش کرد. وقتی برگشت، دختر بهش گفت: «فقط وقتی زنت می‌شم که بابامو دست‌بسته بیاری اینجا!» لنتی با کمک همون دیو، شاه رو آورد. دختر به باباش گفت: «دیدی گفتم بخت و اقبال دست خودمه؟» شاه که مات و مبهوت مونده بود، به عقل دخترش آفرین گفت و تاج شاهی رو داد به لنتی.', is_flagged = 0, quality_score = 90, order_index = 22 WHERE title = 'پادشاه هفت کشور و شاه لعنتی';
UPDATE stories SET content_text = 'پادشاهی بود که بچه‌دار نمی‌شد. یه روز درویشی یه سیب بهش داد و گفت نصفش رو خودش بخوره و نصفش رو زنش. این‌طوری شد که خدا بهشون یه پسر داد به اسم حسن یوسف. اما دایه حواسش پرت شد و بچه رو گذاشت زمین و بچه غیبش زد! از اون طرف، پادشاه یه شهر دیگه دختری داشت که عاشق یه پرنده آبی شده بود. یه روز یه پسر کچل و باهوش، راز پرنده آبی رو کشف کرد؛ فهمید که اون پرنده در واقع یه جوان رعناست که با چهل تا پرنده دیگه که اونا هم دخترای زیبا بودن، طلسم شدن. پسر کچل، دختر پادشاه رو به اون جوان رسوند و اونا با هم ازدواج کردن. وقتی دختر باردار شد، جوان گفت اگه بچه‌مون گریه کنه، اون چهل تا پرنده می‌کشنش. پس دختر فرار کرد و به طور اتفاقی رسید به خونه‌ی مادر حسن یوسف (که همون پرنده آبی بود). وقتی بچه به دنیا اومد، حسن یوسف شب‌ها یواشکی به دیدنشون می‌اومد. مادرش که فهمید، یه تنور داغ کرد. پرنده آبی پرید تو تنور و از سوراخش فرار کرد، اما اون چهل تا پرنده تو آتش سوختن و طلسم باطل شد. این‌جوری حسن یوسف و همسرش به خوبی و خوشی کنار هم زندگی کردن.', is_flagged = 0, quality_score = 90, order_index = 23 WHERE title = 'پرنده آبی';
UPDATE stories SET content_text = 'یه ملای بدجنس با پدر دو تا بچه یتیم عروسی کرد و شد نامادریشون. بچه‌ها از دستش فرار کردن. تو راه پسر از شدت تشنگی آب یه چشمه جادویی رو خورد و تبدیل به آهو شد! دختر که خیلی غصه می‌خورد، با آهو رفتن تو جنگل. یه روز پسر پادشاه دختر رو دید و عاشقش شد و با هم عروسی کردن. اما وقتی شاهزاده رفت سفر، یه پیرزن بدجنس، دختر رو انداخت ته چاه و دختر زشت خودش رو جای اون جا زد. آهو هر روز می‌رفت سر چاه و با خواهرش حرف می‌زد. شاهزاده که برگشت، به زن قلابی شک کرد و وقتی فهمید ماجرا چیه، رفت تو چاه و زن واقعی‌اش و بچه‌شون رو نجات داد. نامادری بدجنس و دخترش هم به سزای اعمال پلیدشون رسیدن و شاهزاده و همسرش سال‌ها به خوبی و خوشی زندگی کردن.', is_flagged = 0, quality_score = 90, order_index = 24 WHERE title = 'پسر پادشاه و پیرزن';
UPDATE stories SET content_text = 'یه پیرمرد هیزم‌شکن بود که یه روز زنش بهش آدرس یه کوه جدید رو داد تا بره هیزم بیاره. پیرمرد رفت و کلی هیزم جمع کرد، اما موقع برگشت دید هیزم‌ها تکون نمی‌خورن. نگو یه ماده‌شیر نشسته روی هیزم‌ها! شیر به پیرمرد گفت: «یا با من ازدواج می‌کنی یا می‌خورمت!» پیرمرد هم از ترس جونش قبول کرد. وقتی می‌خواست برگرده، تیشه و اره‌اش رو داد به شیر و گفت: «اگه بچه‌ای به دنیا آوردی، بگو اینا رو بیاره فلان جا تا بشناسمش.» چند وقت بعد شیر یه پسر قوی به دنیا آورد به اسم شیرعلی. شیرعلی بزرگ شد و یروز سراغ باباشو گرفت. با همون نشونه‌ها رفت و باباش رو پیدا کرد. شیرعلی انقدر قوی بود که به تنهایی بار صدتا درخت نخل رو می‌آورد. آوازه‌ی قدرتش به گوش پادشاه رسید و پادشاه خواست با پهلوان شهر بجنگه. شیرعلی تو میدون پهلوان رو شکست داد و پادشاه از ترس قدرت این پسر، اونو فرستاد دنبال قاطرهای یاغی تو غار دیوها. شیرعلی با زور بازوش دیوها و مارها رو تسلیم کرد و قاطرها رو با بار هیزم آورد. پادشاه که دید حریفش نمیشه، اونو با یه نامه فرستاد پیش حاکم یه ولایت دیگه تا سرشو زیر آب کنن. اما شیرعلی نامه رو پاره کرد و رفت تو شهر اونا غوغا به پا کرد و حاکم و وزیر رو تو خورجین گذاشت و آورد! دست آخر هم رفت و دختر پادشاه رو که اسیر دیو سفید بود، از ته یه چاه تاریک نجات داد. تو این راه حتی رفت دنیای مرده‌ها و با کمک یه سیمرغ مهربون برگشت. شیرعلی بدجنس‌ها رو تنبیه کرد و با دختر پادشاه عروسی کرد و زندگی خوبی راه انداخت.', is_flagged = 0, quality_score = 90, order_index = 25 WHERE title = 'پسر هیزم شکن';
UPDATE stories SET content_text = 'توی روزگارای قدیم، یه شب دزدا زدن به خزانه‌ی پادشاه. فرداش سه نفر رو به عنوان مظنون دستگیر کردن و پادشاه دستور داد هر سه‌تاشون رو اعدام کنن. اما دختر باهوش پادشاه از پدرش مهلت خواست تا دزد واقعی رو از بینشون پیدا کنه. پادشاه قبول کرد. دختر هر شب می‌رفت پیش اون سه نفر و براشون قصه می‌گفت. شب سوم این داستان رو تعریف کرد:
«یه روز دختر یکی از بزرگان شهر تو باغی قدم می‌زد که بدون اجازه گلی چید. به پسرک باغبان گفت بیا این گردنبند رو به جای پول گل بردار. اما پسرک گفت فقط قول بده روز عروسیت با لباس عروس بیای اینجا تا ببینمت! سال‌ها گذشت و روز عروسی دختر فرا رسید. دختر به یاد قولش افتاد و تو همون لباس عروس راهی باغ شد. تو راه، یه دزد، یه مرد چشم‌چران و حتی یه شیر درنده جلوش رو گرفتن؛ اما هر کدوم وقتی ماجرای وفای به عهد دختر رو شنیدن، دلشون به رحم اومد و گذاشتن بره. باغبان هم وقتی دختر رو دید خجالت کشید و دختر صحیح و سالم برگشت.»
قصه که تموم شد، دختر پادشاه از اون سه نفر پرسید: «به نظرتون کدومشون گذشت بیشتری کرد؟» نفر اول گفت: دزد! دومی گفت: مرد چشم‌چران! و سومی گفت: شیر! دختر پادشاه با این ترفند فهمید نفر اول دزد واقعیه، دومی هیزه و سومی شکم‌پرست. این‌طوری بی‌گناه‌ها آزاد شدن و دزد واقعی به سزای عملش رسید.', is_flagged = 0, quality_score = 90, order_index = 26 WHERE title = 'پیدا کردن دزد';
UPDATE stories SET content_text = 'انار خاتونِ زیبا به خاطر حسادت مادرش از خانه رانده شد و با هفت برادر دلاور زندگی تازه‌ای ساخت. اما مادر بدجنسش با سقزی زهرآلود او را مسموم کرد. برادرها که فکر می‌کردند او مرده، پیکرش را با طلا روی اسبی رها کردند. پادشاهی او را یافت، با شیر تازه نجاتش داد و با او ازدواج کرد. مادر کینه‌توز باز هم دست‌بردار نبود؛ فرزندان انار خاتون را کشت و گردن او انداخت! انار خاتون با چشمانی نابینا آواره شد اما با معجزه‌ای، هم خودش و هم فرزندانش شفا یافتند. در نهایت، پادشاه حقیقت را فهمید و عشق و عدالت دوباره در قصر جریان یافت.', is_flagged = 0, quality_score = 89, order_index = 27 WHERE title = 'انار خاتون';
UPDATE stories SET content_text = 'بهرام، پسر یک پیله‌ور فقیر، با مهربانی و دلسوزی، جان یک گربه، یک سگ و یک مار را با تمام دارایی‌اش خرید و آزادشان کرد. مار که فرزند پادشاه مارها بود، در عوض این خوبی، انگشتر سلیمان را به او هدیه داد. بهرام با انگشتر جادویی به ثروتی افسانه‌ای رسید و با دختر پادشاه ازدواج کرد. اما شاهزاده‌ای حسود از توران، با کمک پیرزنی مکار انگشتر را دزدید و همسر بهرام را ربود. حیوانات وفاداری که بهرام نجاتشان داده بود، با فداکاری انگشتر را پس گرفتند و بهرام توانست زندگی و همسر عزیزش را دوباره به دست بیاورد.', is_flagged = 0, quality_score = 89, order_index = 28 WHERE title = 'پیله ور';
UPDATE stories SET content_text = 'یه پادشاهی با خوردن یه سیب جادویی بچه‌دار شد و اسم پسره رو گذاشت «جهان تیغ». پیرمردی که سیب رو داده بود، یه خنجر هم به شکم بچه بست و گفت این جون بچه‌ست. جهان تیغ که بزرگ شد، تو قصر عکس دختری به اسم «چل گیس» رو دید و عاشقش شد و زد به دل جاده. تو راه با دو نفر به اسم «ستاره‌شناس» و «دریانورد» برادر شد. جهان تیغ اژدهاها و شیرهای درنده رو کشت و بالاخره رسید به کوه قاف، جایی که چل گیس اسیر یه طلسم بود. طلسم گربه سیاه رو شکست، چهل تا دیو رو نابود کرد و دختر رو نجات داد. اما یه روز یه پیرزن بدجنس، با کلک خنجر جهان تیغ رو دزدید و اونو انداخت تو چاه و چل گیس رو هم با خودش برد. اما رفقای باوفاش، ستاره‌شناس و دریانورد، پیداش کردن. خنجر رو از ته دریا درآوردن و جون جهان تیغ برگشت. جهان تیغ هم رفت قصر دشمنا، دمار از روزگارشون درآورد و با چل گیس برگشت به شهر خودشون.', is_flagged = 0, quality_score = 89, order_index = 29 WHERE title = 'چل گیس';
UPDATE stories SET content_text = 'پسر کوچولویی بود که خیلی دلش می‌خواست کار کنه و کمک‌حال پدر فقیرش باشه. با اصرار رفت دنبال کار. تو راه خسته و گرسنه شد، یه تیکه نون خورد ولی بازم دلش ضعف می‌رفت. با حسرت گفت: «ای وای!» یهو از تو یه چاه عمیق، یه کوتوله‌ی عجیب با ریش خیلی بلند پرید بیرون و گفت: «من ''ای وای'' هستم! چی می‌خوای؟» پسر گفت می‌خوام کار کنم. ای وای اون رو برد خونه‌اش پیش دخترش. دختر، پسر رو انداخت تو دیگ آب جوش و دوباره زنده‌اش کرد، اما این بار پسر خیلی خوشگل‌تر شده بود! دختر بهش یاد داد چطور به شکل کبوتر، اسب و سگ شکاری دربیاد.
وقتی موعد کار تموم شد، پدر پسر اومد دنبالش. ای وای شرط گذاشت که باید پسرت رو از بین هزار تا کبوتر بشناسی. کبوترِ پسر، پرید رو پای پدرش و نجات پیدا کرد. تو راه برگشت، پسر به شکل یه سگ شکاری طلایی و بعد یه اسب موطلایی دراومد و پدرش اونا رو فروخت تا پولدار بشن. اما ای وای که فهمیده بود، اومد و اسب رو با کلک خرید! پسر که تو دردسر افتاده بود، به شکل ماهی، عقاب و کبوتر دراومد تا از دست ای وای فرار کنه. دست آخر پناه برد به بغل دختر پادشاه. دختر پادشاه عاشقش شد، پسر تبدیل به یه انگشتر جادویی شد و با یه سلسله اتفاقات بامزه و جادویی، دشمنش یعنی ''ای وای'' از بین رفت و پسر شجاع با دختر پادشاه عروسی کرد و خوشبخت شدن.', is_flagged = 0, quality_score = 89, order_index = 30 WHERE title = 'ای وای';
UPDATE stories SET content_text = 'پادشاهی تو شکارگاه عاشق یه دختر چوپان می‌شه و باهاش ازدواج می‌کنه. اما قبل از این‌که دست بهش بزنه، یه صندوقچه پر از جواهر بهش می‌ده و می‌گه: «می‌رم سفر! وقتی برگردم باید تو صندوق به جای جواهر سنگ باشه، یه بچه از من داشته باشی و مادیون و کنیزم هم آبستن باشن!» و خودش راهی سفر می‌شه.
دختر باهوش، لباس مردونه می‌پوشه و زودتر از شاه تو مسیرش اردو می‌زنه و خودشو شاهزاده‌ی مغرب‌زمین جا می‌زنه. تو بازی شطرنج با شاه، شرط می‌بنده و همه‌چیز از جمله اسب و غلام شاه رو می‌بره تا مادیون و کنیزش رو آبستن کنه. صندوقچه رو هم با مهر خود شاه باز می‌کنه و سنگ می‌ریزه توش. دست آخر تو لباس یه کنیز چینی، دل شاه رو می‌بره و ازش باردار می‌شه. وقتی شاه برمی‌گرده و می‌فهمه این همه ماجرا کار همسر باهوششه، عاشقونه تا آخر عمر باهاش می‌مونه.', is_flagged = 0, quality_score = 89, order_index = 31 WHERE title = 'پادشاه و دختر چوپان';
UPDATE stories SET content_text = 'پسر فقیری تصمیم گرفت بره پیش یه جادوگر تا بختش رو باز کنه. تو راه یه پیرزن، یه پیرمرد و یه اژدها رو دید که هر کدوم یه مشکلی داشتن و از پسر خواستن مشکلشون رو از جادوگر بپرسه. وقتی پسر رسید پیش جادوگر، فهمید فقط می‌تونه سه تا سوال بپرسه! پسر فداکاری کرد و بی‌خیال سوال خودش شد و جواب مشکل اون سه نفر رو گرفت. وقتی برگشت، به اژدها گفت چطور پرواز کنه و اژدها هم یه مروارید گنده بهش داد. به پیرمرد کمک کرد خمره‌های طلا رو پیدا کنه و نصف طلاها رو گرفت. به پیرزن هم گفت چطور دختر لالِش رو شفا بده و پیرزن هم دخترش رو به عقد اون درآورد. این‌طوری پسرِ مهربون، با فداکاری و قلب پاکش، هم بخت خودش رو سفید کرد و هم صاحب ثروت و خوشبختی شد.', is_flagged = 0, quality_score = 89, order_index = 32 WHERE title = 'پسر با کله';
