UPDATE stories SET content_text = 'تو یه روز برفی، زنی آرزو کرد دختری داشته باشه با پوستی مثل برف سفید و چشم و ابرویی به سیاهی شب. خدا بهش پریچهر رو داد. اما مادر پریچهر زود از دنیا رفت و نامادری بدجنسی جاش رو گرفت. نامادری که یه آینه جادویی داشت، وقتی فهمید پریچهر ازش زیباتره، به یه شکارچی دستور داد بکشتش. اما شکارچی دلش سوخت و پریچهر رو تو جنگل رها کرد. پریچهر رفت و رفت تا به کلبه‌ی هفت تا کوتوله مهربون رسید. اونا پریچهر رو مثل خواهر خودشون پذیرفتن. پریچهر بزرگ شد و یه روز پسر حاکم که برای شکار اومده بود، دیدش و عاشقش شد. اونا با هم عروسی کردن و نامادری بدجنس از غصه دق کرد و مرد. پریچهر و کوتوله‌ها هم سال‌های سال با خوبی و خوشی کنار هم زندگی کردن.', is_flagged = 0, quality_score = 88, order_index = 47 WHERE title = 'پریچهر و کوتوله ها';
