UPDATE stories SET content_text = 'دو تا برادر تاجر بودن که یکیشون خیلی پولدارتر از اون یکی بود. پسر یکی عاشق دختر اون یکی شده بود، اما عموی پولدار راضی نمی‌شد دخترش رو به برادرزاده‌ی فقیرش بده. پسر و دختر که دیدن چاره‌ای ندارن، یه شب با هم فرار کردن رفتن اصفهان. اونجا پسر از طریق یکی از آشناها رفت پیش شاه عباس و ماجرای عشقشون رو تعریف کرد. یه زمرد قیمتی هم از طرف دختر داد به شاه! شاه عباس هم دختر رو آورد پیش خودش و وقتی دید عشق اونا واقعیه، پدر و مادراشون رو احضار کرد. به عموی مغرور گفت: «حالا این پسر، پسرِ منه! حاضری دخترتو بدی بهش؟» پدر دختر که دید کار از کار گذشته و شاه حامی پسره‌ست، قبول کرد. شاه هم براشون هفت شبانه‌روز جشن گرفت و دستشون رو تو دست هم گذاشت.', is_flagged = 0, quality_score = 78, order_index = 154 WHERE title = 'پسر فقیر که با دختر عموش فرار کرد';
UPDATE stories SET content_text = 'پیرزنی سه تا دختر دم‌بخت داشت که می‌خواست هرطور شده اونا رو بفرسته خونه‌ی بخت. به همین خاطر، هر روز یکی از دخترا رو می‌فرستاد دم در حیاط تا نخ‌ریسی کنه و خودش رو نشون بده. با این ترفند، دختر بزرگ نصیب یه کله‌پز، دختر دومی نصیب یه کبابی و دختر کوچیک نصیب یه عسل‌فروش شد.
یه روز پیرزن تصمیم گرفت بره به دختراش سر بزنه. یه مقدار برگه‌ی قیسی خرید و راه افتاد. خونه‌ی دختر اول، نصف شب از بوی کله‌پاچه وسوسه شد و رفت سر دیگ، اما مچش رو گرفتن و با آبروریزی بیرونش کردن! رفت خونه‌ی دختر دوم؛ اونجا هم نصف شب می‌خواست گوشت کباب رو از قلاب برداره که با سر و صداش بیدار شدن و باز هم از خونه بیرونش کردن. بالاخره رفت خونه‌ی دختر کوچیک که اون شب عروسی دعوت داشتن. تو شلوغی عروسی، پیرزن دستش رو کرد تو کوزه‌ی عسل، اما دستش گیر کرد! برای اینکه کوزه رو بشکنه، نصف شب تو تاریکی اونو کوبید به یه چیز سفت و صاف، که نگو سر بی‌موی یکی از نوازنده‌ها بوده! نوازنده داد و بیداد راه انداخت و پیرزن بازم با خجالت از اونجا رونده شد. آخر سر هم رفت پیش بقال و برگه‌هاشو پس داد، در حالی که آرزوی یه غذای خوشمزه به دلش مونده بود.', is_flagged = 0, quality_score = 78, order_index = 155 WHERE title = 'پیرزن';
UPDATE stories SET content_text = 'تو روزگارای قدیم، پیرزنی زندگی می‌کرد که همدمی جز یه گربه نداشت. این پیرزن حسابی تنبل بود و خونه‌اش همیشه نامرتب بود. یه روز که تصمیم گرفت خونه رو جارو کنه، یه سکه‌ی پنج شاهی پیدا کرد. با خوشحالی رفت و باهاش یه ظرف حلوا خرید و گذاشت رو طاقچه تا بعداً بخوره. اما تا چشمش رو دور دید، گربه‌ی شکمو پرید و حلوا رو خورد و ظرفش رو هم شکست!
پیرزن از صدای شکستن ظرف اومد و از کوره در رفت؛ با دسته جارو محکم کوبید تو سر گربه و سرش رو شکست. گربه هم کم نذاشت و پرید صورت پیرزن رو حسابی چنگ زد. دعوا بالا گرفت تا اینکه همسایه‌ها جداشون کردن و بردنشون پیش قاضی. قاضی وقتی ماجرا رو شنید و سر و وضع دوتاییشون رو دید، با خنده گفت: «تقصیر جفتتونه! تو رو سر گربه‌ات کاکل کاشتی، اونم چشمای تو رو سرمه کشیده!» پیرزن با شنیدن این حرف خنده‌اش گرفت و دست از دعوا کشید و با گربه‌اش به خونه برگشتن.', is_flagged = 0, quality_score = 76, order_index = 156 WHERE title = 'پیرزن و گربه اش';
UPDATE stories SET content_text = 'پرویز، مردی به شدت تنبل بود که همسرش گل‌پری از دستش خسته شد و او را از خانه بیرون انداخت تا کاری پیدا کند. پرویز در صحرا کنار چشمه‌ای پنهان شد و دید درویشی با گل مجسمه‌هایی می‌سازد و آن‌ها را بازخواست می‌کند و می‌شکند. وقتی درویش خواست مجسمه خدا را بسازد و بشکند، پرویز از ترس زلزله و عذاب الهی از بالای درخت فریاد زد: «خانه خراب! خدا را نکش!» درویش از ترس جان داد و پرویز با پول و اثاثیه او با دست پر به خانه برگشت و همسرش با خوشحالی در را به رویش باز کرد.', is_flagged = 1, quality_score = 75, order_index = 157 WHERE title = 'افسانه لری';
