UPDATE stories SET content_text = 'یه تاجر و غلامش توی سفر به شهری رسیدن که پادشاهش مرده بود و می‌خواستن با پرواز یه باز شکاری، پادشاه جدید رو انتخاب کنن. تاجر از غلام پرسید: «اگه باز روی سرت بشینه چیکار می‌کنی؟» غلام گفت: «کاری می‌کنم که روزگار مردم سیاه بشه.» تاجر هم گفت: «اما اگه من شاه بشم به مردم خدمت می‌کنم.» از قضا باز پرواز کرد و صاف نشست رو سر غلام! مردم اول قبول نکردن، ولی سه بار این اتفاق افتاد و بالأخره غلام شد پادشاه شهر. همونطور که گفته بود، روزگار مردم رو سیاه کرد و مالیات‌های سنگین بست تا جایی که مردم آه در بساط نداشتن. یه روز به دستور پادشاه خواستن یه کنیز رو بفروشن اما هیچ‌کس حتی یه سکه هم نداشت، جز پسری که مجبور شد قبر پدرش رو بشکافه تا سکه کفنش رو برداره! تاجر که دید مردم حسابی به تنگ اومدن، رفت پیش پادشاه و شفاعت کرد. پادشاه هم قبول کرد و اوضاع رو بهتر کرد. وقتی تاجر دلیل اون همه ظلم رو پرسید، غلام گفت: «خدا می‌خواست مردم طعم سختی رو بچشن تا قدر عافیت و خوبی رو بدونن.»', is_flagged = 1, quality_score = 75, order_index = 159 WHERE title = 'تاجر و غلام سیاه';
UPDATE stories SET content_text = 'تو ترکمن‌صحرا یه مرد تنبل و ترسو به اسم تاشلی بود که زنش از دستش به تنگ اومد و انداختش بیرون. شب یه مشت مگس دوره‌ش کردن و تاشلی با یه کشیده ده تا مگس رو کشت. با خودش گفت: «عجب پهلوونی هستم!» رفت پیش قاضی و قاضی هم از سر دلسوزی براش رو یه پارچه نوشت: «این تاشلی دلیره، هزارتا رو زمین می‌زنه!» تاشلی این پارچه رو مثل پرچم دستش گرفت و راه افتاد. تو جنگل از ترس نعره می‌کشید که پیرمردی فکر کرد غوله و اسبش رو ول کرد و در رفت. تاشلی با اسب رسید به سرزمین هفت‌تا دیو. دیوها که نوشته روی پرچم رو خوندن، از ترس افتادن به پاش و حسابی تحویلش گرفتن. یه روز ببر درنده‌ای پیدا شد و دیوها تاشلی رو بردن به جنگش. تاشلی از ترس رفت بالای درخت، ولی از شدت لرزش پرت شد رو کمر ببر! ببر هم از ترس فرار کرد. دیوها که فکر کردن این نشونه شجاعتشه، ببر رو کشتن و خواهرشون رو دادن به تاشلی و اون شد حاکم سرزمین دیوها!', is_flagged = 1, quality_score = 75, order_index = 160 WHERE title = 'تاشلی پهلوان';
UPDATE stories SET content_text = 'روزی روزگاری سه تا خواهر بودن که از مال دنیا فقط یه نردبون، یه سنگ آسیاب و یه سگ پاکوتاه (تل) داشتن. خواهر کوچیک سگ رو برداشت و باهاش راهی شد. رفتن تو یه خرابه زندگی کردن. سگ هر روز می‌رفت خونه پادشاه، غذا می‌دزدید و می‌آورد. تا اینکه یه روز پسر پادشاه رد سگ رو زد و رسید به خرابه. همونجا یه دل نه صد دل عاشق دختر شد و بردش به قصر و باهاش عروسی کرد. مادر پسر پادشاه مدام به دختر طعنه می‌زد که تو بی‌کس و کاری. سگ که دید دختر غصه‌داره، رفت و براش چند تا برادر قلابی جور کرد! یه روز سگ می‌خواست وفاداری دختر رو امتحان کنه، خودش رو زد به مردن. دختر اولش محل نذاشت، اما وقتی دید سگ ناراحت شده، کلی گریه کرد و ازش عذرخواهی کرد. وقتی هم که سگ واقعاً مرد، دختر اون رو با احترام شست، لای پنبه گذاشت و گذاشتش تو یه صندوقچه. وقتی شوهرش صندوق رو باز کرد، دید به جای یه سگ مرده، یه سگ طلایی و قشنگ اونجاست! دختر با گریه گفت اینو برادرام برام سوغات آوردن. اینجوری سگ باوفا تا بعد از مرگش هم آبروی دختر رو حفظ کرد.', is_flagged = 0, quality_score = 75, order_index = 161 WHERE title = 'تل';
UPDATE stories SET content_text = 'پیرزنی پسری داشت به اسم «تنبلو» که خیلی بی‌حال و تنبل بود. یه روز پیرزن مجبورش کرد بره کنار آب دست و رویش رو بشوره. اونجا یه گل پیدا کرد و تو بازار فروختش به یه تاجر ثروتمند. تاجر گفت اگه درخت این گل رو بیاری، هر چی بخوای بهت می‌دم! تنبلو رفت رد آب رو گرفت تا رسید به یه باغ عجیب. اونجا دختری رو دید که سرش بریده شده و هر قطره خونش تبدیل به یه گل می‌شه! تنبلو فهمید کار کارِ یه دیوه. رفت و پنهان شد. دیو شبا می‌اومد، با یه روغن جادویی دختر رو زنده می‌کرد و صبح‌ها دوباره سرش رو می‌برید. تنبلو از روی دست دیو تقلب کرد و تو غیابش دختر رو زنده کرد. به دختر گفت جای شیشه عمر دیو رو ازش بپرسه. دختر هم با زبون‌بازی جای شیشه رو که تو شکم یه ماهی، تو شکم یه گاو، ته یه چاه بود، فهمید! تنبلو رفت و شیشه عمر رو آورد. دیو که فهمید کارش تمومه، التماس کرد. تنبلو به شرطی که تمام آدم‌های کشته شده تو غار رو زنده کنه، باهاش راه اومد. دیو همه رو زنده کرد، اما تنبلو آخر سر شیشه عمرش رو زد زمین و دیو تبدیل شد به یه شمش طلا. تاجر هم دخترش رو (که همون دختر توی باغ بود) به عقد تنبلو درآورد و از اون به بعد به تنبلو می‌گفتن پهلوون!', is_flagged = 0, quality_score = 75, order_index = 162 WHERE title = 'تنبلو';
UPDATE stories SET content_text = 'پیرمردی بود که بهش می‌گفتن «توس‌وچه». یه روز که داشت برای پدرش غذا می‌برد، تو جنگل یه خرس جلوش رو گرفت و گفت خورش غذات رو بده وگرنه خودتو می‌خورم! توس‌وچه از ترس خورش رو داد. فردا و پس‌فردا هم همین اتفاق افتاد و توس‌وچه بهانه‌های مختلفی برای پدرش آورد. روز سوم، وقتی خرس رو دید، پرید بالای یه درخت خرمالو (خرماندو). خرس اومد پایین درخت و گفت: «شاخه زیر پات رو بشکن تا خرمالوهاش رو بخورم!» توس‌وچه از ترس شکست. خرس دوباره گفت: «اون یکی شاخه رو هم بشکن!» توس‌وچه گول خورد و شاخه‌ای که دستش بود رو هم شکست و افتاد پایین! خرس فوری اونو انداخت تو گونی و برد در خونه‌ی پیرزن (مادر توس‌وچه) و گفت: «دیگ رو پر آب کن که برات گوشت آوردم!» پیرزن بی‌خبر، آب رو جوش آورد و خرس توس‌وچه رو انداخت تو دیگ درش رو بست و فرار کرد. پیرزن وقتی در دیگ رو برداشت، با دیدن پسرش تو آب جوش دنیا رو سرش خراب شد و با ناله و شیون نشست به گریه و زاری، اما دیگه کار از کار گذشته بود و خرس فرار کرده بود.', is_flagged = 0, quality_score = 75, order_index = 163 WHERE title = 'توس وچه و خرس';
UPDATE stories SET content_text = 'تو روزگارای قدیم یه پسر تنها به اسم «تونگ‌تونگ» بود و شش تا برادر قلدر که بهشون می‌گفتن لولو. اونا به ارابه‌های تونگ‌تونگ حسادت کردن و همه‌شون رو آتیش زدن. تونگ‌تونگ خاکسترها رو ریخت تو کیسه و رفت شهر. اتفاقی دختر پادشاه افتاد رو کیسه و خاکسترها پخش شد. تونگ‌تونگ الکی داد و بیداد کرد که اینا جواهر بوده! شاه هم یه کیسه طلا بهش داد. وقتی برگشت، لولوها ماجرا رو پرسیدن و اونم گفت: «شهر دور خاکستر رو با طلا عوض می‌کنن.» لولوها هم ارابه‌هاشون رو آتیش زدن و رفتن شهر، اما مردم حسابی کتکشون زدن! لولوها با عصبانیت برگشتن و تو دعوا زدن مادر پیر تونگ‌تونگ رو کشتن. تونگ‌تونگ مادرش رو گذاشت رو الاغ و رفت یه مزرعه. صاحب مزرعه اومد الاغ رو بزنه که جنازه پیرزن افتاد. تونگ‌تونگ باز شلوغش کرد که «مادرم رو کشتی!» صاحب مزرعه از ترس دخترش رو داد بهش. وقتی برگشت، باز به لولوها دروغ گفت که «مرده رو با زن عوض می‌کنن.» لولوها هم مادرشون رو کشتن و رفتن شهر، اما دوباره کتک مفصلی خوردن! این بار لولوها تونگ‌تونگ رو انداختن تو رودخونه. اما تونگ‌تونگ شناگر بود، نجات پیدا کرد و جون یه چوپان رو هم خرید و با کلی گوسفند برگشت. لولوها دوباره پرسیدن: «از کجا آوردی؟» تونگ‌تونگ گفت: «ته رودخونه هر عددی بگی همونقدر گوسفند می‌دن.» لولوهای طمع‌کار همه‌شون پریدن تو آب و غرق شدن و تونگ‌تونگ با خیال راحت زندگیش رو کرد.', is_flagged = 0, quality_score = 75, order_index = 164 WHERE title = 'تونگ تونگ تنها و شش تا لولو';
UPDATE stories SET content_text = 'یه زن و شوهری بودن به اسم چرتان و پرتان که یه دختر خیلی خوشگل داشتن. یه روز پسر حاکم دختره رو دید و عاشقش شد و باهاش عروسی کرد. چرتان و پرتان که دلشون تنگ شده بود، با دو تا نون ساده راه افتادن رفتن قصر دیدن دخترشون. دختر از هدیه اونا خجالت کشید و خودش یه کادوی گرون گرفت و داد به شوهرش. این پدر و مادر از بس ساده و نادون بودن، تو قصر کلی دسته‌گل به آب دادن! غاز و مرغای حاکم رو انداختن تو آب‌جوش که تمیز بشن، خشتای طلای اتاق رو انداختن دور که راحت بخوابن! وقت برگشتن، دخترشون بهشون یه کیسه پول و عسل و لباس داد که برن. اما این دو تا تو راه باز شاهکار کردن؛ زمین ترک‌خورده رو دیدن، فکر کردن گشنه‌شه، عسل‌ها رو ریختن تو زمین! نی‌زار رو دیدن که تو باد تکون می‌خوره، فکر کردن سردشه، لباساشون رو پوشوندن به نی‌ها! کفششون رو هم دادن به یه قورباغه که قورقور می‌کرد. آخرش هم با پولاشون یه گوسفند گرفتن. پرتان داشت گوسفنده رو پوست می‌کند که دید یه زنبور نشسته رو سر چرتان. یهو با کارد محکم زد رو سر شوهرش که زنبوره رو بکشه، اما شوهر بیچاره درجا مرد!', is_flagged = 0, quality_score = 75, order_index = 165 WHERE title = 'چرتان و پرتان';
UPDATE stories SET content_text = 'دو تا برادر تاجر بودن. محمود، پسر برادر کوچیکه، قرار بود با دخترعموش ازدواج کنه. اما شب عروسی، یه زنی محمود رو گول زد و برد خونه‌ش. محمود اونجا عاشق دختر اون زن شد و قول داد باهاش عروسی کنه. این‌جوری شد که عروسی با دخترعموش به هم خورد. حسن، برادر اون دختره، کینه به دل گرفت. محمود هر شب پنهانی می‌رفت پیش خواهر حسن و دخترعموی بیچاره‌ش که هنوز عاشقش بود، براش در رو باز می‌ذاشت. تا اینکه دخترعمو از غصه دق کرد و سم خورد و مرد. حسن که فهمید، تصمیم گرفت انتقام بگیره. تو قهوه محمود و زنش (خواهر خودش) سم ریخت. محمود فهمید و نخورد، اما زنش خورد و مرد. وقتی حسن اومد و دید محمود زنده‌ست، حسابی از خجالتش دراومد و یه بلایی سر محمود آورد که از غصه دق کرد و مرد! عموی محمود که دید حسن انتقام دخترش رو گرفته، دختر خواهرشو به عقد حسن درآورد و قصه به سر رسید.', is_flagged = 0, quality_score = 75, order_index = 166 WHERE title = 'چگونگی تقاص گرفتن حسن';
UPDATE stories SET content_text = 'روزی روزگاری یه تاجر خسیس بود که به غلام سیاهش فقط روزی دو تا نون خشک می‌داد. یه روز که رفت مهمونی و حسابی خورد، به غلامش گفت چرا تو از این غذاها نمی‌پزی؟ غلام گفت: «وقتی در انبارها رو قفل زدی من با چی بپزم؟» فرداش تاجر کلیدها رو داد، اما غلام هرچی می‌خواست برداره یه صدای غیبی می‌گفت: «دست نزن، امانته!» تاجر خودش با عصبانیت رفت انبار، اما همون صدا رو شنید که می‌گفت: «این مال باقر آهنگره!» تاجر که حسابی ترسیده و حرصی شده بود، تموم داراییش رو سکه کرد، ریخت تو یه عصای توخالی و راهی بیابون شد. اما از قضا یه روز آب رودخونه عصا رو برد و تاجر از هستی ساقط شد و به گدایی افتاد. از اون طرف، باقر آهنگر که مرد عیال‌وار و فقیری بود، وقتی داشت هیزم می‌شکست، همون سکه‌ها تو حیاطش بارید! باقر با اون پول یه مسافرخونه ساخت تا به غریب‌ها مجانی غذا بده. یه روز گذر تاجرِ گدا افتاد به مسافرخونه‌ی باقر. باقر شناختش و بهش محبت کرد، حتی زنش چند تا نون پخت و توش سکه گذاشت و داد به تاجر تا تو راه بخوره. اما تاجر از همه‌جا بی‌خبر، نون‌ها رو داد به یه پینه‌دوز و به جاش کفش گرفت. پینه‌دوز هم نون‌ها رو آورد داد به مسافرخونه‌ی باقر آهنگر! زن باقر تا نون‌ها رو دید خندید و گفت: «مال حلال همیشه برمی‌گرده سر جای اولش.»', is_flagged = 0, quality_score = 75, order_index = 167 WHERE title = 'باقر آهنگر';
UPDATE stories SET content_text = 'یکی بود یکی نبود. تو یه دهی یه خانواده زندگی می‌کردن که تازه پسرشون رو داماد کرده بودن. یه روز همه رفتن شهر و عروس تو خونه تنها موند. سر ظهر عروس داشت ناهار می‌خورد که یه اتفاق خجالت‌آور براش افتاد. یهو دید یه بزغاله گوشه اتاق داره سر تکون می‌ده! عروس بیچاره فکر کرد بزغاله همه‌چی رو فهمیده و می‌خواد به شوهرش بگه. از ترس آبروش رفت تمام طلاها و گردنبندهاشو انداخت گردن بزغاله تا حق‌السکوت بده! عصر مادرشوهر اومد و دید طلاهای عروس گردن بزغاله‌ست. عروس با گریه ماجرا رو گفت. مادرشوهر گفت: «غصه نخور، منم کمکت می‌کنم تا پدرشوهرت نفهمه!» و طلاهای خودشم انداخت گردن بزغاله! پدرشوهر که اومد خونه، دید بزغاله غرق طلاست. وقتی فهمید قضیه چیه، گفت: «بیاید یه کاری کنیم پسرم نفهمه.» و رفت لباس‌های خودشو پوشوند تن بزغاله! خلاصه وقتی پسر برگشت و این صحنه خنده‌دار رو دید و فهمید خانواده‌اش چقدر ساده‌لوح هستن، کلافه شد و از ده زد بیرون. رفت تا رسید به یه ده دیگه. دید مردم اونجا بلد نیستن حتی یه ظرف بشورن! بعد رفت یه ده دیگه، دید یه عروس قدبلند دارن و چون از در رد نمی‌شه، می‌خوان سر یا پاشو ببرن! مرد با دست زد پس گردن عروس، عروس خم شد و رفت تو! همه فکر کردن معجزه کرده. بعد رفت یه جای دیگه، به یه خانواده گفت از جهنم اومدم. اونا هم باور کردن و کلی پول بهش دادن تا برای مرده‌هاشون تو جهنم ببره! مرد با خودش گفت: «بابا اینا که از خانواده منم شوت‌ترن!» پشیمون شد و برگشت پیش خانواده خودش تا با همون سادگی شون زندگی کنه.', is_flagged = 0, quality_score = 75, order_index = 168 WHERE title = 'بز فضول';
UPDATE stories SET content_text = 'در زمان‌های قدیم، پادشاهی بود که پسر جوانی داشت. این پسر هر روز با نوکراش می‌رفت شکار. یه روز تو شکارگاه متوجه خیمه‌هایی شد و فهمید دختر پادشاه چین و ماچین اونجا اردو زده. پسر که تعریف زیبایی دختر رو شنید، رفت دیدنش و درجا عاشقش شد. ازش پرسید: «شوهر داری؟» دختر گفت: «نه، هر کی میاد، بابام یه شرط‌های عجیبی می‌ذاره که پشیمون می‌شن.» پسر گفت: «اگه من بیام زنم می‌شی؟» دختر قبول کرد. پسر رفت پیش پدرش و ماجرا رو گفت. پادشاه هم وزیرش رو برای خواستگاری فرستاد چین و ماچین. پادشاه اونجا سه تا شرط عجیب گذاشت: اول، کسی که بتونه هفت دیگ برنج رو یه جا بخوره! دوم، کسی که تو آتیش نسوزه! سوم، کسی که در یک چشم به هم زدن جوجه سیمرغ رو از کوه قاف بیاره! وزیر ناامید برگشت، اما پادشاه خندید و گفت: «غصه نخور، من آدمش رو دارم!» سه نفر رو صدا کرد: «بللئوک» که معده‌اش ته نداشت، «آوانداز» که انگار تو شکمش دریا بود، و «شلنگ‌انداز» که قدش به آسمون می‌رسید. همه با هم رفتن چین و ماچین. بللئوک هفت دیگ برنج رو درسته قورت داد! آوانداز رفت وسط کوه آتیش و با آب شکمش همه رو خاموش کرد! شلنگ‌انداز هم با یه قدم رفت کوه قاف و جوجه سیمرغ رو آورد! پادشاه چین و ماچین که مات و مبهوت مونده بود، مجبور شد دخترش رو به پسر پادشاه بده و اونا با هم عروسی کردن.', is_flagged = 0, quality_score = 75, order_index = 169 WHERE title = 'بللئوک، آوانداز، شلنگ انداز';
UPDATE stories SET content_text = 'یه خواهر و برادر بودن که گیر یه زن بابای بدجنس افتاده بودن. یه روز زن بابا به پدر بچه‌ها گفت: «پسرت رو بکش تا گوشتش رو بخوریم!» پدر سنگدل هم پسرش رو کشت و داد به زنش. خواهر بیچاره با چشم گریون استخون‌های برادر رو تو باغچه خاک کرد. مدتی گذشت تا اینکه از قبر برادر یه بوته سبز شد و یه هندونه داد. خواهر وقتی هندونه رو شکست، یه بلبل قشنگ از توش پرید بیرون! بلبل پر کشید رفت پیش زن بابا و با آواز خوند: «من بلبل بودم، دربه‌در بودم!» زن بابا گفت دوباره بخون. بلبل گفت: «چشمتو ببند و دهنتو باز کن.» بعد یه مشت سوزن ریخت تو دهن زن بابا! بعد رفت پیش پدرش و همون آواز رو خوند. پدر هم که چشماشو بست، بلبل سوزن ریخت تو حلق اونم. آخر سر رفت پیش خواهر مهربونش و تو آوازش همه چی رو گفت. خواهر وقتی دهنشو باز کرد، بلبل که همون داداشش بود، یه مشت نخود کشمش خوشمزه ریخت تو دهنش تا کامش شیرین بشه.', is_flagged = 0, quality_score = 75, order_index = 170 WHERE title = 'بلبل';
UPDATE stories SET content_text = 'یه روز پسر پادشاه سخت مریض می‌شه. پادشاه نذر می‌کنه اگه پسرش خوب بشه، یه حوض پر از عسل و روغن بین مردم پخش کنه. پسر خوب می‌شه و پادشاه نذرشو ادا می‌کنه. شاهزاده از روی شیطنت، کوزه‌ی یه پیرزن رو می‌شکنه. پیرزن هم نفرینش می‌کنه و می‌گه: «برو که الهی گیر بلبل خیارک بیفتی!» پسر کنجکاو می‌شه و می‌پرسه بلبل خیارک چیه؟ پیرزن می‌گه: «کنار یه دریای دور، یه بوته خیاره که سه تا خیار کوچیک داره. تو هر کدوم از این خیارها، یه دختر فوق‌العاده زیباست.» شاهزاده راه می‌افته و خیارها رو پیدا می‌کنه. از بین اونا فقط دختر سومی زنده می‌مونه. شاهزاده اونو می‌ذاره بالای درخت گردو تا بره و برگرده. اما یه دختر کولی حسود سر می‌رسه و دختر رو تو استخر غرق می‌کنه. از تو استخر یه کره اسب دریایی میاد بیرون. کولی از روی حسادت اون کره رو هم می‌کشه! اما از خون کره اسب، یه درخت زیبا سبز می‌شه... در همین حین، پادشاه چین و ماچین برای دخترش خواستگار می‌خواد اما شرط‌های سختی می‌ذاره: خوردن هفت دیگ برنج، نسوختن تو آتیش و آوردن جوجه سیمرغ از کوه قاف! شاهزاده سه تا آدم عجیب به اسم‌های بللئوک، آوانداز و شلنگ‌انداز رو می‌فرسته و اونا تمام شرط‌ها رو انجام می‌دن تا شاهزاده به مراد دلش برسه.', is_flagged = 0, quality_score = 75, order_index = 171 WHERE title = 'بلبل خیارک';
UPDATE stories SET content_text = 'توی یه خونه نقلی، یه دختر با پدر و مادرش زندگی می‌کرد. یه شب پدر گفت: «من امشب مهمونم و خونه نمیام.» و رفت. مادر به دخترش گفت: «پاشو در رو ببند.» دختر تنبلی کرد و گفت: «بذار این نخ رو بتابم بعد.» همون موقع، یه مرد غول‌پیکر و ترسناک اومد تو و سلام کرد. مادر دستپاچه شد و به دختر گفت: «بفرما، حرف گوش نکردی، حالا بیا جواب اینو بده!» مرد غول‌پیکر با پررویی گفت: «مهمون اومده براتون، چای و قلیون نمیارین؟» مادر به دختر اشاره کرد و دختر با ترس و لرز چای آورد. بعد غول گفت: «شام چی؟» دختر بازم رفت و شام آورد. غول که حسابی جا خوش کرده بود گفت: «رختخواب پهن نمی‌کنین؟» مادر که فهمید این غول ول‌کن نیست، نقشه کشید. گفت: «ما قبل خواب عادت داریم آب گرم بریزیم رو سرمون.» یه دیگ بزرگ آب جوش گذاشت رو آتیش. غول گفت: «اول شما.» مادر گفت: «نه، شما مهمونی، اول شما.» غول با غرور رفت ایستاد رو تخته‌سنگی که درِ چاه بود. مادر زرنگ تو یه چشم به هم زدن آجر زیر تخته‌سنگ رو کشید! غول با سر افتاد ته چاه و مادر دیگ آب جوش رو هم خالی کرد رو سرش! این‌طوری مادر و دختر از شر اون مزاحم ترسناک خلاص شدن.', is_flagged = 0, quality_score = 75, order_index = 172 WHERE title = 'بنه کی';
UPDATE stories SET content_text = 'بهلول و خلیفه بغداد برادر هم بودن. یه روز بهلول بچه‌های شهر رو جمع کرد برد کنار دریا و با هم یه کلبه‌ی کوچیک و نقلی ساختن. همون روز خلیفه هم با دو تا از زناش برای گردش اومده بودن لب دریا. زن بزرگِ خلیفه از کلبه‌ی بهلول خوشش اومد و پرسید: «این کلبه رو به من می‌فروشی؟» بهلول گفت: «در عوضش چی بهم می‌دی؟» زن گفت: «یه قطاب خوشمزه برات می‌پزم.» بهلول که شکمو بود، سه بار گفت: «قبوله، راضیم!» تو همین حین زن کوچیکِ خلیفه به این معامله می‌خندید. زنا برگشتن خونه. زن کوچیک شب تو خواب دید که زن بزرگ تو یه قصر باشکوه تو بهشت نشسته! از خواب پرید. سه بار خوابید و بیدار شد و هر سه بار همون خواب رو دید. صبح کله‌ی سحر رفت پیش بهلول و گفت: «کلبه‌ت رو به صد تا سکه طلا می‌خرم!» اما بهلول قبول نکرد. زن هرچی اصرار کرد فایده نداشت.
زن که حسابی لجش گرفته بود، پیراهن خودش رو پاره کرد، دوید پیش خلیفه و با گریه دروغکی گفت: «برادرت بهلول می‌خواست بهم دست‌درازی کنه، لباسمو پاره کرد و من به زور فرار کردم!» خلیفه خون جلو چشماش رو گرفت، شمشیر کشید و داد زد: «بهلول کجاست؟!»
بهلول که می‌دونست چه خبره، یه دیگ، یه تیکه کرباس و یه بیل برداشت و رفت تو قبرستون. یه قبر کَند و وایساد کنارش. خلیفه اومد و داد زد: «الان سرتو از تنت جدا می‌کنم!» بهلول با آرامش گفت: «ما که برادریم، بیا دستتو بده به من، پاتو بذار رو پای من، یه روبوسی کنیم بعد منو بکش. کفنمم که آماده‌س.» خلیفه تا پاشو گذاشت رو پای بهلول و دست داد، بهلول با یه حرکت سریع چرخید و خلیفه رو چنان پرت کرد که به اندازه هزار سال راه دور شد!
خلیفه وقتی به هوش اومد، دید تو یه جای ناشناخته‌س. رفت و رفت تا رسید به یه ده. از هر کی آدرس بغداد رو می‌پرسید، کسی نمی‌دونست. تا اینکه گفتن برو پیش یه پیرمرد صدساله شاید اون بدونه. خلیفه رفت پیش پیرمرد. پیرمرد به زنش گفت: «زری، زیرپوش مهمون رو بنداز!» زن از جاش تکون نخورد. پیرمرد چند بار گفت فایده نداشت، آخرش خودش پاشد نمد انداخت، یه کتک حسابی به زنش زد و غذا آورد! خلیفه گفت: «تا آدرس بغداد رو ندی غذا نمی‌خورم.» پیرمرد گفت: «من نمی‌دونم، برو پیش برادرم که دویست سالشه.»
خلیفه یه روز دیگه راه رفت تا رسید به پیرمرد دویست ساله. اون پیرمرد تا مهمون اومد، به زنش گفت نمد بندازه. زنش با غرغر و نق‌نق پاشد کارا رو کرد و غذا آورد. خلیفه بازم گفت اول آدرس بغداد! پیرمرد گفت: «منم نمی‌دونم، برو پیش داداش بزرگم که سیصد سالشه.»
خلیفه با بدبختی رسید به خونه پیرمرد سیصدساله. زنش که حامله هم بود، تا مهمون رو دید با خوش‌رویی سریع فرش انداخت، پاهای خلیفه رو شست و غذا آورد. پیرمرد سیصدساله به خلیفه گفت: «آدرس دقیق رو نمی‌دونم، اما تو زیارتگاه ما یه درختی هست که یه پرنده هر روز میاد روش می‌شینه، دعا می‌خونه و به سمت بغداد پرواز می‌کنه.» بعد از غذا، پیرمرد به زنش گفت: «یه هندونه بیار.» زن با اون شکم بزرگ، چهل پله رفت پایین تو سرداب و یه هندونه آورد. پیرمرد فشارش داد و گفت: «این خوب نیست یکی دیگه بیار.» زن بدون هیچ اعتراضی سه بار رفت پایین و همون هندونه رو آورد تا پیرمرد راضی شد!
خلیفه با تعجب پرسید: «تو سیصد سالته ولی از برادر صد ساله‌ت جوون‌تری، رازت چیه؟» پیرمرد خندید و گفت: «راز تو زنه! زن برادر صدو‌ساله‌ام لجبازه، زن برادر دویست‌ساله‌ام غرغروعه، اما زن من فرشته‌س، ببین با یه دونه هندونه چطور با خوش‌رویی حرفمو گوش داد.»
صبح خلیفه رفت زیارتگاه، تا پرنده خواست پرواز کنه، چنگ زد به پاهاش و رفت هوا! پرنده اونو درست تو همون قبرستون پیش بهلول انداخت زمین. خلیفه که تازه قدر عافیت رو فهمیده بود، دست بهلول رو بوسید و با هم رفتن قصر. بعدشم دستور داد زن دروغگوش رو به سزای عملش رسوندن و همون‌جا خاکش کردن.', is_flagged = 0, quality_score = 75, order_index = 173 WHERE title = 'بهلول دانا و خلیفه بغداد';
UPDATE stories SET content_text = 'یه روزی یه پسری عاشق یه دختر میشه و با هم عهد می‌بندن که اگه یکی‌شون مرد، اون یکی دیگه ازدواج نکنه. از قضا دختره بدجوری مریض میشه و دکترا جوابش می‌کنن. پسره هم از روی وفاداری و غصه، به خودش آسیب جدی می‌زنه. اما در کمال ناباوری دختره خوب میشه و میگه من شوهر می‌خوام! پسره هم که دیگه نمی‌تونست کاری کنه، دختره رو به عقد غلام سیاهش درمیاره تا حداقل پیش خودش بمونن.
سال‌ها بعد، یه آدمی که دنبال «بی‌غم‌ترین آدم دنیا» می‌گشت، به این جوون می‌رسه و با دیدن زندگی مرفه و ظاهر آرومش فکر می‌کنه بالاخره آدم بی‌غم رو پیدا کرده. اما وقتی جوون قصه‌ی تلخ عشقش رو تعریف می‌کنه، مرد می‌فهمه که هیچ‌کس تو این دنیا بدون درد و غصه نیست.', is_flagged = 1, quality_score = 75, order_index = 174 WHERE title = 'بی غم دنیا';
UPDATE stories SET content_text = 'یه تاجر ثروتمند بود که پسرش با دخترعموش نامزد بود. پسر برای عید فطر و غدیر کلی هدیه برای نامزدش فرستاد. دم عید نوروز که شد، پسر به پدرش گفت که دیگه هدیه نمی‌فرستم چون اون هیچی برام نفرستاده. اما پدرش گفت که این کار رو بکنه. پسر هم یه گردنبند الماس و گوشواره فرستاد. دختر هم در جواب، یه ساعت جیبی، انگشتر عقیق، قوطی سیگار نقره و یه دست لباس کامل فرستاد. اما وقتی هدیه‌ها رسید، پسر خونه نبود و پدرش ساعت رو برای خودش برداشت! چند روز بعد عموی پسر متوجه شد که ساعت دست پسر نیست و بهش گفت که کار پدرشه. پسر هم رفت و یواشکی ساعت و انگشتر رو از صندوق پدرش برداشت. شب عروسی، پدر می‌خواست انگشتر رو به عنوان رونما بده به عروس، اما دید ای دل غافل، نیست! مجبور شد گردنبند مروارید زنش رو بده. وقتی هم دید انگشتر دست عروسه، حسابی حرص خورد. خلاصه فرداش پسر به پدرش گفت: «من دیگه می‌خوام روی پای خودم وایستم و مستقل بشم!» و این‌طوری حسابش رو از پدر طمع‌کارش جدا کرد.', is_flagged = 0, quality_score = 75, order_index = 175 WHERE title = 'پدری که هدیه پسرش را برای خودش ورداشت';
UPDATE stories SET content_text = 'یکی بود یکی نبود. تاجری بود که یه پسر یکی‌یدونه داشت. دم مرگ به پسرش نصیحت کرد که قدر مال و ثروت رو بدونه و اگه روزی همه‌چیزش رو از دست داد و خواست خونه‌ش رو بفروشه، اول یه بار پله‌های ایوون رو خراب کنه و از نو بسازه. پسر بعد از مرگ پدر رفیق‌باز شد و همه‌چیز رو به باد داد. وقتی به پیسی خورد، یاد وصیت پدر افتاد. وقتی پله‌ها رو خراب کرد و با مکافات دوباره ساخت، تازه فهمید پدرش چقدر برای این ثروت زحمت کشیده بوده. دوباره دست به کار شد و پولدار شد. بعدش با یه کوسه رفیق شد. یه روز شنیدن دختر پادشاه عکسی از خودش تو آب نشون میده و صد تومن می‌گیره. رفتن اونجا و با کلی مسخره‌بازی و نقش بازی کردن، خودشون رو آدم‌های بی‌دست‌وپا و دهاتی نشون دادن. دختر پادشاه که دلش سوخته بود، بردشون تو قصر. اونا با نقشه‌های خنده‌دارشون کاری کردن که آخر سر دختره بهشون پول داد تا فقط دست از سرش بردارن و برن!', is_flagged = 1, quality_score = 75, order_index = 176 WHERE title = 'پسر تاجر و کوسه';
UPDATE stories SET content_text = 'یه چوپون کچل و ساده‌دل تو یه دهات زندگی می‌کرد. یه روز از حضرت موسی خواست که از خدا بخواد اوضاعش رو بهتر کنه. خدا هم تقدیرش رو به اندازه‌ی نوک مژه‌ی مورچه تغییر داد! نتیجه‌ش این شد که چوپون از کار بی‌کار شد! اما تو همین آوارگی با یه تاجر آشنا شد و رفت تهران و حسابی خوش‌تیپ و باکلاس شد. از قضا، تاجر دخترش رو به پسر وزیر نامزد کرده بود و پسر چوپون شده بود پادوی اونا. روز عروسی، پسر چوپون لباس فاخری که براش دوخته بودن رو پوشید و این‌قدر خوش‌تیپ شده بود که وقتی رفت جلوی شاه، شاه با خودش گفت حیف این پسر نیست؟ همون‌جا شاه تصمیم گرفت دختر خودش رو بده به این جوون! فرداش وزیر اعتراض کرد که چرا دختر شاه رو دادی به یه پسر بی‌اصل‌ونسب؟ اما شاه با هوش خودش ثابت کرد که این پسر هم شجاعت داره و هم تقدیرش بلنده. این‌طوری چوپون ساده‌دل قصه‌ی ما شد جانشین پادشاه.', is_flagged = 0, quality_score = 75, order_index = 177 WHERE title = 'پسر دهاتی به مقام پادشاه رسید';
UPDATE stories SET content_text = 'دو تا برادر بودن؛ یکی خیلی کاری و اون یکی حسابی تنبل. یه روز برادر کاری خسته شد و برادر تنبل رو از خونه انداخت بیرون. پسر تنبل راه افتاد تو بیابون تا رسید به یه دیو. حسابی ترسید ولی به روی خودش نیاورد و با زرنگی به دیو گفت: «پدر تو هفت تا دیو به من بدهکاره! حالا تو رو می‌برم تا شش تای دیگه رو هم پیدا کنم.» دیو که حسابی ترسیده بود، التماس کرد و پسر رو برد خونه‌شون. دیوها هفت تا بودن و هر روز می‌رفتن سر کار. قرار شد پسر هم باهاشون زندگی کنه و کار کنه. یه روز دیوها بهش گفتن برو هیزم بیار. پسر که تا حالا دست به سیاه و سفید نزده بود، رفت تو جنگل، یه طناب بزرگ بست دور چند تا درخت و نشست. دیوها اومدن و گفتن: «چیکار می‌کنی؟» پسر گفت: «می‌خوام یه دفعه کل درخت‌ها رو بکنم ببرم که دیگه خیالمون راحت بشه!» دیوها گفتن: «خب بکن ببینیم!» پسر دید ضایع شده، گفت: «اصلاً من دیگه نمی‌خوام با شما شریک باشم، سهمم رو بدین برم.» دیوها هم که از کارای عجیب غریبش کلافه شده بودن، دو تا بشقاب طلا بهش دادن. پسر برگشت خونه، با طلاها هم خودش زن گرفت و هم برادرش، و زندگیشون روبه‌راه شد.', is_flagged = 0, quality_score = 75, order_index = 178 WHERE title = 'پسر و دیوها';
UPDATE stories SET content_text = 'یکی بود یکی نبود. یه مرد ساده‌دلی بود که زنش حسابی بهش خیانت می‌کرد. این زن مکار، غذاهای چرب و نرم رو می‌داد به رفیقش و نون خشک و بی‌کیفیت رو می‌ذاشت جلوی شوهر بیچاره‌اش. مرد یه روز اعتراض کرد که چرا نون ما این‌قدر خشکه؟ زن فریبکار هم گفت: «تقصیر خواهرته که تو بغداد زندگی می‌کنه و باد، آردای نرم ما رو می‌بره اونجا!» مرد ساده‌لوح حرفش رو باور کرد و رفت بغداد پیش خواهرش تا گله کنه. خواهر که زن دانایی بود، فهمید کاسه‌ای زیر نیم‌کاسه است. به روی خودش نیاورد اما خواهرزاده‌ی زیرک و کچل مرد رو باهاش همراه کرد تا دست زن‌دایی رو رو کنه. 
کچل با نقشه‌های هوشمندانه‌اش چند بار مانع دیدار زن‌دایی و رفیقش شد. در نهایت، زن مکار که دید کچل همه‌چیز رو فهمیده، رفت پیش یه درخت مقدس (پیرآغاجی) تا نذر کنه که کچل کور بشه! اما کچل از قبل رفته بود تو چاه کنار درخت قایم شده بود و به جای درخت جواب می‌داد و می‌گفت که خواسته‌اش رو برآورده می‌کنه. زن با خوشحالی برگشت خونه و فکر کرد کچل و شوهرش کور شدن. اما همون شب که رفیقش مخفیانه اومده بود تو خونه، دایی و کچل با چوب افتادن به جونش و حسابی دکش کردن.', is_flagged = 1, quality_score = 75, order_index = 179 WHERE title = 'پیرآغاجی';
UPDATE stories SET content_text = 'تو یه روز سرد، بزی که بچه‌های نازش (شنگول و منگول) رو یه گرگ بدجنس خورده بود، تصمیم گرفت بره انتقام بگیره. بز رفت بالای لونه‌ی گرگ و با سُمش محکم کوبید رو سقف. گرگه با صدای کلفتش پرسید: «کیه کیه داره بام منو تکون میده؟» بز با شجاعت جواب داد: «منم منم بزوله! دو شاخ دارم تیزوله! هر کی خورده شنگم، هر کی خورده دنگم، فردا میام به جنگم!» 
گرگه که با پررویی شنگول و منگول رو خورده بود، گفت: «من خوردم شنگت، من خوردم دنگت! فردا می‌بینمت تو میدون جنگ!» بز که می‌دونست برای جنگ با گرگ باید سلاح محکمی داشته باشه، مقداری از شیر تازه‌اش رو دوشید و برد پیش استاد آهنگر تا شاخ‌هاش رو براش تیز و برنده کنه. اینطوری آماده شد تا حساب گرگ بدجنس رو کف دستش بذاره.', is_flagged = 0, quality_score = 75, order_index = 180 WHERE title = 'پیرزن و بز';
UPDATE stories SET content_text = 'پیرزنی با زرنگی تمام هر سه دخترش رو با نشوندن پشت چرخ نخ‌ریسی دم در خونه، به عقد یه کله‌پز، یه کبابی و یه عسل‌فروش درآورد. یه روز تصمیم گرفت بهشون سر بزنه. خونه‌ی داماد اول، نصف شب هوس کله‌پاچه کرد اما دستش رو شد و دخترش بیرونش کرد! خونه‌ی داماد دوم خواست کباب بخوره، ولی دستش به گوشتا نرسید و باز هم با سر و صدا همه رو بیدار کرد و اخراج شد! دست آخر رفت خونه‌ی دختر کوچیکه که اتفاقاً اون شب عروسی یکی از آشناهاشون بود. پیرزن یواشکی رفت سراغ کوزه‌ی عسل، اما دستش گیر کرد. نصف شب می‌خواست کوزه رو بشکنه که تو تاریکی به جای سنگ، کوزه رو کوبید تو سر طاس یکی از نوازنده‌ها! با صدای فریاد مرد بیچاره، باز هم آبروریزی شد و پیرزن با همون برگه‌های قیسی که خریده بود، ناامید و گرسنه برگشت خونه‌اش.', is_flagged = 0, quality_score = 75, order_index = 181 WHERE title = 'پیرزن و سه دخترش';
UPDATE stories SET content_text = 'خواهر و برادری به نام‌های شکر حوا و سبزه‌قبا از سر نداری در غاری زندگی می‌کردند. روزی خرسی وارد غار شد و خواهر را فریب داد تا برادرش را بکشند. خواهر که حالا پسری به نام زنگلی‌پر داشت، با خرس نقشه کشیدند تا سبزه‌قبا را مسموم کنند. اما زنگلی‌پر که متوجه ماجرا شده بود، دایی‌اش را خبر کرد. دایی با هوشیاری نقشه آن‌ها را نقش بر آب کرد. در نهایت، با کمک خواهرزاده شجاعش، خرس را از پا درآورد و خواهر بی‌وفایش را نیز به سزای عملش رساند تا دیگر هیچ خیانتی بی‌پاسخ نماند.', is_flagged = 0, quality_score = 70, order_index = 182 WHERE title = 'افسانه';
UPDATE stories SET content_text = 'پسر جوانی با راهنمایی پدرش تصمیم گرفت دوستانش را امتحان کند. آن‌ها لاشه گوسفندی را در عبایی پیچیدند و پسر به دوستانش گفت که در یک درگیری آدم کشته است و نیاز به کمک دارد. اما در کمال ناباوری، هیچ‌کدام از دوستانش حاضر نشدند به او پناه بدهند و هر یک بهانه‌ای آوردند. این اتفاق درس بزرگی به جوان داد تا تفاوت میان دوستان واقعی و رفقای روزهای خوشی را به خوبی درک کند.', is_flagged = 0, quality_score = 70, order_index = 183 WHERE title = 'امدک یگن';
UPDATE stories SET content_text = 'تات محمد، مردی مهربان و ثروتمند بود که همسایگان حسودش تمام دارایی‌اش را غارت کردند. او که از این همه ظلم به تنگ آمده بود، تصمیم گرفت با هوش و زیرکی به آن‌ها درس بزرگی بدهد. با نقشه‌هایی حساب‌شده، همسایگان طمع‌کار را فریب داد؛ آن‌ها از شدت طمع ابتدا خانه‌هایشان را آتش زدند و در نهایت به طمع یافتن گوسفند، خود را در رودخانه غرق کردند. تات محمد که حق خود را پس گرفته بود، در آرامش و با خیال راحت به زندگی‌اش در کنار همسرش ادامه داد.', is_flagged = 1, quality_score = 70, order_index = 184 WHERE title = 'تات محمد لر';
UPDATE stories SET content_text = 'دو تا رفیق روز تعطیل تصمیم گرفتن برن بیرون. یکی گفت: «بیا بریم مسجد و نماز بخونیم و کار ثواب کنیم.» اون یکی گفت: «نه بابا، بیا بریم عرق بخوریم و خوش بگذرونیم!» اولی رفت مسجد ولی تا پاشو گذاشت بیرون، یه آجر افتاد تو سرش و سرش شکست. دومی رفت دنبال عیاشی و تو راه صد تومن پول پیدا کرد! غروب که همدیگه رو دیدن، خیلی تعجب کردن. رفتن پیش یه دانای شهر تا بپرسن چرا اونی که کار خوب کرده بلا سرش اومده و اون یکی پول گیرش اومده؟ دانا بهشون گفت: «تو که رفتی مسجد، امروز مقدر شده بود که بمیری و آوار رو سرت خراب بشه، اما به خاطر راه خدایی که رفتی، خدا رحم کرد و فقط یه آجر سرت رو شکست. اما تو یکی که راه شیطون رو رفتی، مقدر بود هزار تومن پیدا کنی، ولی چون گناه کردی نهصد تومنش پرید و فقط صد تومنش نصیبت شد!»', is_flagged = 0, quality_score = 70, order_index = 185 WHERE title = 'تعبیر رای خدا';
UPDATE stories SET content_text = 'یه پسر تنبل بود که مادرش برای بیرون کردنش از خونه، یه سیب دم در گذاشت و وقتی پسر رفت سیب رو برداره، در رو روش بست! پسر آواره شد و یکی به شوخی بهش گفت برو بازار اصفهان پول ریخته! پسر رفت و شروع کرد به خاک‌بازی و گشتن. یه مرد که فهمید قضیه چیه، بهش کار داد و گفت آشغال‌های تو کوچه رو جمع کن و بیار بریز تو شترخان من. مرد از فروش همون آشغال‌ها کلی پول درآورد و مزد خوبی به تنبل داد. تنبل تو بازار به یه گدای کور پول داد، اما کور با کلک کیسه پولش رو دزدید! تنبل هم افتاد دنبال کور تا رسید به پاتوق هفت تا گدای کور. دید اینا شبا پلو می‌خورن و با کیسه‌های ده تومنی قمار بازی می‌کنن! تنبل همه پول‌هاشون رو گرفت و هر هفت‌تاشون رو کشت. بعد کورها رو پیچید تو نمد و یواش‌یواش داد به یه حمال تا ببردشون بندازه تو آب. حمال بیچاره هر بار می‌رفت و برمی‌گشت می‌دید جسد سر جاشه! خلاصه تنبل با یه عالمه پول و اسب برگشت خونه. مادرش اول در رو باز نمی‌کرد، اما وقتی دید پسرش با خورجین پر از پول اومده، با روی باز استقبال کرد و سال‌ها به خوبی زندگی کردن.', is_flagged = 0, quality_score = 70, order_index = 186 WHERE title = 'تنبل و کور';
UPDATE stories SET content_text = 'یکی بود یکی نبود. یه زنی بود که سه تا دختر داشت. از قضا زبون هر سه تای این دخترا می‌گرفت و نمی‌تونستن درست حرف بزنن. یه روز که مادره می‌خواست بره مهمونی، به دختراش حسابی سپرد که: «مبادا اگه کسی اومد دم در، حرفی بزنیدها! یهو دیدی خواستگاره، می‌فهمه زبونتون می‌گیره و می‌ذاره می‌ره.» دخترا هم گفتن چشم. مادره رفت و دخترا ساکت و صامت نشستن گوشه اتاق. مگس‌ها هم ول‌کن نبودن و هی دور سرشون می‌چرخیدن. یهو یه زن غریبه اومد دم در و هرچی صدا زد، کسی جواب نداد. سرشو آورد تو اتاق و دید دخترا لال مونی گرفتن. زن غریبه با تعجب گفت: «وا مصیبتا! اینا چرا اینجورین؟» دختر بزرگه که دید اوضاع خرابه و زنه داره فکرای بد می‌کنه، خواست مگس‌ها رو کیش کنه و گفت: «تیس تیس مدسینا!» (کیش کیش مگس‌ها!). خواهر وسطی که اینو شنید، هول شد و گفت: «مده ننه مو ندف حف نتتینا؟» (مگه ننه‌مون نگفت حرف نزنید؟). خواهر آخری هم که خیلی بهش برخورده بود، با افتخار گفت: «الحمد و تنينا ته من پیس تسی حرف نتتینا!» (الحمدلله که من پیش کسی حرف نزدم!). زنه که دید اینا هم زبونشون می‌گیره و هم عقل درست درمونی ندارن، پاشد رفت و دیگه پشت سرشم نگاه نکرد!', is_flagged = 1, quality_score = 70, order_index = 187 WHERE title = 'تیس تیس مدسینا';
UPDATE stories SET content_text = 'بز زنگوله‌پا که دنبال بچه‌های عزیزش می‌گشت، درِ خونه‌ی تک‌تک حیوونای جنگل رو زد. همه قسم خوردن که بچه‌هاش رو نخوردن، تا اینکه رسید به خونه‌ی خرس گنده. با شجاعت رو به خرس کرد و خوند: «منم منم بزک زنگوله‌پا، می‌جهم با هر دو پا! کی خورده انگله من؟ کی خورده دنگله من؟ کی خورده منگله من؟ کی میاد به جنگ من؟» خرس که چشمش به بز افتاده بود و طمع کرده بود اونو هم یه لقمه‌ی چپ کنه، خرناسه‌ای کشید و با صدای کلفتی جواب داد: «من خوردم انگله تو! من خوردم دنگله تو! من خوردم منگله تو! من میام به جنگ تو!»', is_flagged = 0, quality_score = 70, order_index = 188 WHERE title = 'انگله من، دنگله من، منگله من';
UPDATE stories SET content_text = 'دو تا برادر بودن که یکی‌شون عاقل بود و اون‌یکی یه کم شیرین‌عقل! اونا دو تا گاو داشتن که تموم دارایی‌شون بود. یه روز برادر شیرین‌عقل گیر داد که باید یکی از گاوها رو بفروشیم. گاو رو برد بیابون و به خیال خودش فروختش به یه مارمولک! گاو رو ول کرد و رفت، گرگ‌ها هم اومدن گاو بیچاره رو خوردن. فرداش که رفت پولش رو از مارمولک بگیره، با کندن زمین یه کوزه‌ی پر از جواهر پیدا کرد. با خوشحالی جواهرا رو آورد خونه و برادر عاقل حسابی جا خورد! گذشت و یه روز پسر پادشاه اومد در خونه‌شون. برادر دیوانه تو یه درگیری اتفاقی زد پسر پادشاه رو کشت و انداختش تو چاه! برادر عاقل که دید اوضاع پسِ، سریع یه بز رو انداخت تو همون چاه. وقتی مامورای پادشاه اومدن، برادر شیرین‌عقل راستش رو گفت که جسد تو چاهه. اما وقتی رفت پایین، داد زد: «پسر پادشاه شاخ داره و ریشش بلنده!» پادشاه که فکر کرد این مرد واقعاً دیوانه‌ست و داره مسخره‌بازی درمیاره، دستور داد سنگ‌بارونش کنن. این‌طوری شد که برادر شیرین‌عقل جونش رو از دست داد و برادر عاقل موند و اون کوزه‌ی پر از جواهر.', is_flagged = 0, quality_score = 70, order_index = 189 WHERE title = 'برادر عاقل و دیوانه';
UPDATE stories SET content_text = 'تو روزگاران قدیم، زن و شوهری با دختر و پسرشون به خوبی زندگی می‌کردن تا اینکه مادر بچه‌ها مرد و مرد یه زن دیگه گرفت. زن بابا چشم دیدن بچه‌ها رو نداشت. یه روز که می‌خواست غذا بپزه، همه گوشت‌ها رو خودش خورد! برای اینکه آبروش نره، یه نقشه شوم کشید. پسرک بیچاره رو کشت و انداخت تو دیگ غذا! پدر که از سر کار اومد، از همه‌جا بی‌خبر نشست به غذا خوردن. هر تیکه‌ای که می‌خورد می‌پرسید: «این چیه؟» و زن بابا با بی‌رحمی می‌گفت: «بخور و حرف نزن!» خواهر دلسوز که می‌دونست چی شده، با گریه استخون‌های برادرش رو جمع کرد، با گلاب شست و پای بوته گل خاک کرد. یهو از روی خاک، یه بلبل زیبا پر کشید! بلبل رفت نشست رو بیل پدرش و با آواز تموم ماجرا رو خوند. بعد به پدر گفت دهنتو باز کن! تا دهنشو باز کرد، بلبل یه درفش انداخت تو گلوش و پدره مرد. بعد رفت سراغ زن بابای بدجنس، آواز خوند و یه مشت سوزن ریخت تو حلق اون و کشتش! آخر سر رفت پیش خواهر مهربونش، براش خوند و وقتی خواهر دهنشو باز کرد، یه شاخه نبات شیرین انداخت تو دهنش.', is_flagged = 1, quality_score = 70, order_index = 190 WHERE title = 'بلبل';
UPDATE stories SET content_text = 'یه مادر و پسری بودن که خیلی فقیر بودن. یه بار تو یه مهمونی، پادشاه با لباس مبدل اومد پیششون و دید که چقدر آدمای خوبی هستن. پادشاه یه گوساله‌ی چموش به پسر داد تا کار کنه. وقتی دید پسر چقدر زبر و زرنگه، دختر تنبل خودش رو کرد تو یه گونی و به جای گندم داد به پسر! پسر وقتی فهمید دختر پادشاه تو گونیه، هیچی نگفت و بهش کار داد. به مادرش گفت: «هرکسی که کار کنه، حق داره نون بخوره!» دختر تنبل پادشاه که دید چاره‌ای نداره، یواش‌یواش دست به کار شد و پشم ریسید و حسابی زرنگ شد. روزی که پادشاه و وزیر اومدن بهشون سر بزنن، دیدن دختر داره کار می‌کنه و می‌گه «هرکی کار نکنه نون نداره!» پادشاه که از زرنگی پسر و تغییر دخترش خیلی خوشحال شده بود، اونا رو به عقد هم درآورد و هفت شبانه‌روز براشون جشن گرفت.', is_flagged = 0, quality_score = 70, order_index = 191 WHERE title = 'پسر زرنگ و دختر تنبل پادشاه';
UPDATE stories SET content_text = 'باری بود و باری نبود. پیرزنی بود که در حسرت داشتن یه بچه می‌سوخت. یه روز دلش گرفت، کوزه‌ی شیره‌اش رو برداشت، با مداد براش چشم و ابرو کشید، یه چارقد سرش کرد و گذاشتش پشت پنجره و گفت: «اینم دختر قشنگ من!» از قضا، همون روز پسر پادشاه از اونجا رد می‌شد و با دیدن چهره‌ی پوشیده‌ی پشت پنجره، یک دل نه صد دل عاشق شد. ملکه رو فرستاد خواستگاری. پیرزن بیچاره از ترس دست و پاش رو گم کرد و کوزه رو فقط از پشت پرده یه لحظه به ملکه نشون داد. ملکه هم پسندید و بساط عروسی به پا شد!
روز حمام رفتن عروس که رسید، پیرزن کوزه رو برد حمام. اما از بخت بد، کوزه از دستش سر خورد و شکست! پیرزن از غصه شروع کرد به زدن تو سر و صورتش. همون لحظه، یه غول سیاه برزنگی که رو پشت‌بام بود، از دیدن این صحنه زد زیر خنده. خندیدن همانا و پریدن استخوانی که مدت‌ها تو گلوش گیر کرده بود، همانا! غول به جبران این لطف، خودش رو به شکل یه دختر زیبارو درآورد و به جای عروس با پیرزن همراه شد. پسر پادشاه وقتی عروس به اون زیبایی رو دید، از خوشحالی بال درآورد و هفت شبانه‌روز جشن گرفتن.', is_flagged = 1, quality_score = 70, order_index = 192 WHERE title = 'پیر برزنگی و کوزه شیر';
UPDATE stories SET content_text = 'یکی بود یکی نبود. یه پیرزن مهربون بود که می‌خواست بره خونه‌ی دخترش. تو راه، اول به یه شغال رسید. شغال گفت: «اگه می‌خوای نخورمت، تو برگشت برام یه خروس بیار!» پیرزن قول داد. جلوتر به یه گرگ رسید؛ گرگ هم ازش یه گوسفند خواست. بعدشم یه شیر جلوش سبز شد و گفت: «باید برام یه گوساله بیاری!» پیرزن چاره‌ای نداشت و به همشون قول داد.
وقتی رسید خونه‌ی دخترش و ماجرا رو تعریف کرد، دخترش یه فکر بکر کرد. موقع برگشت، مادرش رو گذاشت توی یه کدوی بزرگ و قلش داد سمت خونه. شیر کدو رو دید و پرسید: «خاله پیرزن رو ندیدی؟» پیرزن از تو کدو با صدای عوض‌شده گفت: «نه، ندیدم، یه قلی بده منو!» شیر هم کدو رو قل داد. گرگ و شغال هم گول خوردن، اما شغال شک کرد و دنبال کدو راه افتاد. وقتی رسیدن نزدیک خونه، پیرزن از کدو اومد بیرون. شغال که قضیه رو فهمید، رفت شیر و گرگ رو خبر کرد و متأسفانه دسته‌جمعی ریختن سر پیرزن بی‌نوا.', is_flagged = 0, quality_score = 70, order_index = 193 WHERE title = 'پیرزن قلقلی زن';
UPDATE stories SET content_text = 'پینه‌دوزی همسری شلخته و بی‌خیال داشت که مدام در کوچه‌ها می‌چرخید. روزی با اصرار شوهرش قرار شد پنبه بریسه، اما خسته شد و وسایلش را به رودخانه انداخت و به جایش آجری برداشت که از قضا طلا از آب درآمد! زن به جای نگهداری از طلا، آن را با حلوا عوض کرد و وقتی حلواها حرفش را گوش ندادند، آن‌ها را کتک زد. در ادامه ماجراهای خنده‌دار و عجیبی پیش آمد؛ از مهمان کردن یک شتر تا بردن درِ خانه به دوشش برای محافظت از آن! در نهایت پینه‌دوز با زیرکی از این دردسرها خلاص شد.', is_flagged = 1, quality_score = 65, order_index = 194 WHERE title = 'پینه دوز و زن دیوانه';
UPDATE stories SET content_text = 'عباس، یه پسر کچل و تنبل بود که یه روز مادرش از خونه بیرونش کرد تا بره کار کنه. عباس هم به جای کار، رفت زیر سایه‌ی درخت می‌خوابید و دروغ می‌گفت که کار کرده. آخرش با یه حقه‌ی زیرکانه سر یه کدخدای طمع‌کار رو کلاه گذاشت و یه عالمه گندم ازش گرفت. تو راه برگشت هم سر چند نفر دیگه رو با حقه‌های خنده‌دار کلاه گذاشت و رسید خونه. کدخدا و بقیه که فهمیده بودن گول خوردن، با عصبانیت اومدن دم خونه‌ی عباس. عباس هم به مادرش گفت خودش رو بزنه به مردن. وقتی اونا اومدن، عباس زد زیر گریه و داد و بی‌داد که شما مادرم رو کشتید! اونا هم از ترس جونشون فرار کردن و دیگه پشت سرشونم نگاه نکردن و عباس و مادرش با اون همه گندم موندن و صفا کردن!', is_flagged = 0, quality_score = 65, order_index = 195 WHERE title = 'پسر کچل';
UPDATE stories SET content_text = 'مرد زحمتکشی بود که همسری بی‌وفا و بدذات داشت. زن، دسترنج شوهر را به دوستانش می‌داد و به او نان سبوس‌دار می‌خوراند. مرد با راهنمایی خواهرش متوجه ماجرا شد و خواهرزاده‌اش را به خانه برد تا مراقب اوضاع باشد. زن بی‌وفا که خواهرزاده را سد راه خود می‌دید، با نقشه‌ای شوم قصد جان او را کرد، اما پسرک با زیرکی در مزار «پیر کلوک سوز» پنهان شد و زن را فریب داد. در نهایت، با درایت پسرک، دست زن و شریک جرمش رو شد و به سزای اعمال پلیدشان رسیدند.', is_flagged = 1, quality_score = 60, order_index = 196 WHERE title = 'پیر کلوک سوز';
UPDATE stories SET content_text = 'مردی سه تا زن داشت و برای اینکه هر کدوم رو پیش خودش عزیز کنه، به زن بزرگش یه سینه‌ریز، به دومی یه گوشواره و به کوچیکترینشون یه انگشتر داد. به هر کدوم هم یواشکی گفت: «هر وقت گفتم قربون اون نشونه‌دارم برم، بدون منظورم تویی!» یه روز صبح، زن‌ها برای اینکه به همدیگه پز بدن، نشونه‌هاشون رو به رخ هم کشیدن و تازه فهمیدن که شوهرشون چه کلکی سوار کرده! شب که مرد اومد خونه، هر کدوم از زن‌ها شروع کردن به غرولند و قهر کردن. مرد هم با چرب‌زبونی برای هر کدوم بهونه‌ای آورد تا آرومشون کنه. یه مدت گذشت و زن اول رفت مسافرت. سرِ یه غذایی که پخته بودن، مرد حسابی تعریف کرد و بین زن دوم و سوم سر اینکه کی غذا رو پخته دعوا شد و زن کوچیکتر قهر کرد و از خونه رفت.', is_flagged = 1, quality_score = 60, order_index = 197 WHERE title = 'تاجر و سه تا زن نشونه دارش';
UPDATE stories SET content_text = 'یه زنی بود که یه پسر و چند تا گوسفند داشت. پسرک هر روز گوسفندها رو می‌برد چرا. یه روز یه گرگ اومد و به پسر گفت: «خودتو بخورم یا گوسفنداتو؟» پسر رفت از مادرش پرسید. مادرش گفت: «گوسفندها حیفن، بگو خودتو بخوره!» گرگ هم پسر رو خورد، اما یه تیکه از پسرک افتاد رو زمین. گرگ گوسفندها رو برد تحویل مادر پسر داد. اون یه تیکه از پسرک جون گرفت، چند تا نون برداشت و راه افتاد بره پیش پادشاه تا ارث پدرشو بگیره. تو راه، گرگ، روباه و اژدها باهاش همراه شدن و پسر با قدرت جادویی اونا رو تو دل خودش قایم کرد! رسید به یه جوی آب و از زنا خواست دستمالشو بشورن، وقتی نشستن، پسر کل آب چشمه رو هم تو خودش کشید. وقتی رسید پیش پادشاه و ارث باباشو خواست، پادشاه خندید و دستور داد بندازنش جلو حیوونای درنده. پسر اژدها رو آزاد کرد و همه حیوونا رو خورد. پادشاه گفت بندازنش زیر دست و پای اسب‌ها؛ پسر گرگ رو آزاد کرد تا اسب‌ها رو فراری بده. پادشاه که کفری شده بود گفت بندازنش تو تنور؛ پسر همه‌ی آب‌ها رو ریخت رو آتیش و خاموشش کرد. آخر سر پادشاه تسلیم شد و فرستادش خزانه. پسر کل طلاها رو برداشت و با خوشحالی برگشت خونه. به مادرش گفت اونو تو گونی کنه و با چوب بزنه تا ازش سکه بریزه، و واقعاً هم کلی طلا ریخت بیرون!', is_flagged = 1, quality_score = 60, order_index = 198 WHERE title = 'پسر و گرگ';
UPDATE stories SET content_text = 'یه پسر بود که هیچ‌کاری نمی‌کرد و می‌گفت خدا خودش روزی می‌ده. اسمشم گذاشته بودن یه اسم زشت و بی‌ادبانه! یه روز هفت‌تا خمره طلا پیدا کرد، ولی زحمت نکشید بیاردشون، تا اینکه همسایه‌ی طمع‌کار خمره‌ها رو دزدید و از شانس پسر، پر از طلا شدن! پسر با اون پولا رفت یه گربه، یه کبوتر و یه مار رو خرید و جونشون رو نجات داد. مار هم اونو برد پیش حضرت سلیمان و یه انگشتر جادویی بهش داد. پسر با همون انگشتر یه قصر رویایی ساخت و با دختر پادشاه عروسی کرد. اما یه پادشاه غریبه چشمش دختر رو گرفت و با یه پیرزن مکار دختر و قصر رو دزدید! اینجاست که حیوونایی که پسر جونشون رو نجات داده بود به دادش رسیدن؛ کبوتر پرواز کرد و گربه انگشتر رو از پیرزن دزدید. پسر هم انگشتر رو گرفت، همه‌چیز رو برگردوند و حسابی پیروز شد.', is_flagged = 1, quality_score = 50, order_index = 199 WHERE title = 'پسرک بی‌خیال';
